INSERT INTO public."Muscle_Group" (id, name, image_url, preview_image, created_at, updated_at) VALUES
    ('7df0c585-9bbd-5c63-9a30-283d15a44b10'::uuid, 'Antebrazos', NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('5a839e32-5e44-5e45-84c3-d39e1be5306e'::uuid, 'Cardio/Full Body', NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03')
INSERT INTO public."Muscle" (id, muscle_group_id, name, description, image_url, preview_image, created_at, updated_at) VALUES
    ('dcd9529a-28c3-5b72-a8a4-33c58e445517'::uuid, '7df0c585-9bbd-5c63-9a30-283d15a44b10'::uuid, 'Braquiorradial', 'El braquiorradial recorre la parte externa del antebrazo desde el húmero hasta la muñeca. Flexiona el codo, sobre todo con agarre neutro o prono. Da volumen al antebrazo. Ejercicios principales: curl martillo, curl reverso y hammer curl en polea.', NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('38f24334-df2c-5d1c-9c33-29ae515364a8'::uuid, '7df0c585-9bbd-5c63-9a30-283d15a44b10'::uuid, 'Musculatura de Agarre', 'La musculatura de agarre engloba los flexores profundos de los dedos y la mano. Es determinante para sostener cargas pesadas, dominadas y levantamientos olímpicos. Ejercicios principales: farmer carry, dead hang y plate pinch.', NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('89e7f5df-db26-538c-9a34-749ca830aeb0'::uuid, '5a839e32-5e44-5e45-84c3-d39e1be5306e'::uuid, 'Sistema Cardiovascular', 'El sistema cardiovascular abarca corazón, pulmones y vasos sanguíneos. Se entrena con trabajo metabólico de alta demanda que mejora la capacidad aeróbica y anaeróbica. Ejercicios principales: assault bike, remo ergómetro, burpees y comba.', NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('167ff0ae-a830-57f3-831d-843e32dbba78'::uuid, '5a839e32-5e44-5e45-84c3-d39e1be5306e'::uuid, 'Cuerpo Completo', 'El trabajo de cuerpo completo integra cadenas musculares en un solo patrón coordinado. Característico del crossfit y el levantamiento olímpico, demanda potencia, estabilidad y transferencia de fuerza. Ejercicios principales: clean and jerk, thruster y snatch.', NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('bf59e6f7-bb94-541f-9754-d3e10efaa691'::uuid, '964d1770-1aac-4cf7-825c-780f96b17bb2'::uuid, 'Flexores de Cadera', 'Los flexores de cadera (psoas ilíaco principalmente) conectan la columna lumbar con el fémur. Elevan el muslo hacia el tronco y estabilizan la pelvis. Ejercicios principales: elevaciones de rodillas, knees to elbows y marcha.', NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('1c145019-a447-5ef0-83ad-28ce5cf9ce89'::uuid, '5a839e32-5e44-5e45-84c3-d39e1be5306e'::uuid, 'Musculatura del Cuello', 'La musculatura del cuello (esternocleidomastoideo y trapecio superior) estabiliza la cabeza ante impactos. Es clave en deportes de contacto para absorber golpes y reducir el riesgo de conmoción. Ejercicios principales: neck flexion, neck bridge y trabajo isométrico.', NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03')
INSERT INTO public."Exercise" (id, name, description, safety_tips, activation_tips, video_url, preview_image, bg_image, created_at, updated_at) VALUES
    ('261782d8-b619-58f6-aff2-9b60928afedb'::uuid, 'Sentadilla con Barra Alta', 'La sentadilla con barra alta apoya la barra sobre el trapecio superior y mantiene el torso más vertical. Descendé flexionando cadera y rodillas a la vez hasta romper la paralela, manteniendo los talones apoyados, y empujá el piso para subir. Enfatiza el cuádriceps por el rango de rodilla amplio.', 'Mantené la columna neutra y el core firme durante todo el recorrido. No dejes que las rodillas colapsen hacia adentro y evitá redondear la zona lumbar en el fondo.', 'Antes de la serie hacé movilidad de tobillo y cadera, y activá glúteos con un par de sentadillas con banda. Buscá tensión en todo el cuerpo antes de descender.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('0bd03725-9b75-5fdd-b713-98bbf4ada440'::uuid, 'Peso Muerto Convencional', 'El peso muerto convencional levanta la barra desde el suelo hasta la extensión completa de cadera. Colocá los pies a la anchura de cadera, agarrá la barra fuera de las piernas y empujá el piso manteniendo la espalda recta. Es el ejercicio rey para la cadena posterior.', 'Mantené la barra pegada al cuerpo y la columna neutra en todo momento. Nunca tires con la espalda redondeada ni hiperextiendas el lumbar al bloquear arriba.', 'Generá tensión tirando ligeramente de la barra antes de despegarla del suelo. Activá dorsales llevando la barra contra los muslos.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('0eb35e1a-d2b9-5db6-b31c-8150e78d31e9'::uuid, 'Peso Muerto Sumo', 'El peso muerto sumo usa una postura ancha con los pies hacia afuera y las manos por dentro de las piernas. Reduce el rango de recorrido y la demanda lumbar, aumentando la participación de glúteos y aductores. Empujá las rodillas hacia afuera mientras extendés la cadera.', 'Mantené el pecho alto y la espalda neutra durante el despegue. Evitá que las caderas suban antes que el pecho.', 'Abrí las rodillas en línea con los pies y traccioná los dorsales antes de despegar. Activá aductores tomando posición ancha.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('ae44805a-6931-55e1-aafb-a4f7e2462b6b'::uuid, 'Press de Banca Plano', 'El press de banca plano empuja la barra desde el pecho hasta la extensión de los codos acostado sobre un banco. Bajá la barra controlada hasta tocar la línea del pezón y empujá hacia arriba y ligeramente atrás. Es el principal ejercicio de fuerza de empuje horizontal.', 'Mantené las escápulas retraídas y los pies firmes en el piso. Nunca rebotes la barra en el pecho ni dejes que los codos se abran en exceso.', 'Retraé y deprimí las escápulas para crear una base estable. Apretá la barra fuerte para activar tríceps y pecho.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('82d61884-5659-5b9b-a71b-f19ec4362ae9'::uuid, 'Press de Banca Inclinado', 'El press inclinado se realiza con el banco a 30-45 grados, enfatizando la porción clavicular del pectoral. Bajá la barra hacia la parte alta del pecho y empujá hasta extender los codos. Construye la parte superior del pecho.', 'No subas demasiado el ángulo del banco para no transferir el trabajo al hombro. Mantené las muñecas alineadas con los antebrazos.', 'Activá el pectoral superior haciendo un par de aperturas inclinadas livianas. Fijá las escápulas antes de empezar.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('e94d30b5-329a-562a-91eb-d5875345bc5b'::uuid, 'Press Militar con Barra', 'El press militar empuja la barra desde la altura de los hombros hasta encima de la cabeza, de pie. Mantené el core y los glúteos firmes para no arquear la espalda y empujá la cabeza levemente hacia adelante al pasar la barra. Es el rey del empuje vertical.', 'Evitá hiperextender la zona lumbar; mantené el abdomen y los glúteos contraídos. No dejes la barra adelantada al bloquear.', 'Activá el core y el glúteo antes de empujar. Hacé unas elevaciones frontales livianas para preparar el deltoides.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('b03565cd-a3b5-5af0-9fe1-6beb6c22230b'::uuid, 'Remo con Barra Pendlay', 'El remo Pendlay parte de la barra en el suelo en cada repetición, con el torso paralelo al piso. Tirá explosivo hacia el abdomen bajo y bajá controlando. Desarrolla potencia y grosor en la espalda media.', 'Mantené la espalda completamente neutra y paralela al suelo; no uses impulso de cadera excesivo. Cuidá la lumbar en la posición inclinada.', 'Retraé las escápulas al iniciar el tirón y activá dorsales pensando en llevar los codos atrás.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('ba54bcf2-4709-550e-817e-96986073f43b'::uuid, 'Remo con Barra Inclinado', 'El remo con barra inclinado mantiene el torso a unos 45 grados y tira la barra hacia el abdomen de forma continua. Trabaja el grosor de la espalda permitiendo cargas altas. Bajá controlando el estiramiento del dorsal.', 'Mantené la espalda neutra y evitá usar demasiado balanceo de cadera. No redondees la lumbar bajo carga.', 'Activá el dorsal iniciando el tirón desde el codo, no desde la mano. Retraé escápulas antes de cada repetición.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('81909633-9160-5a5f-9b30-99ff1b5db93b'::uuid, 'Dominadas Pronas', 'Las dominadas pronas se ejecutan colgado de la barra con agarre prono más ancho que los hombros, traccionando hasta superar la barbilla. Desarrollan la amplitud del dorsal y la fuerza de tirón vertical. Bajá hasta la extensión completa controlando.', 'Evitá los tirones bruscos y el balanceo descontrolado. No bajes de golpe para proteger los hombros y codos.', 'Deprimí las escápulas antes de tirar e iniciá el movimiento llevando los codos hacia las costillas.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('db74320d-550e-5129-9d96-c538545d83e1'::uuid, 'Dominadas Supinas', 'Las dominadas supinas usan agarre supino a la anchura de hombros, aumentando la participación del bíceps junto al dorsal. Traccioná hasta llevar el pecho a la barra y bajá controlado hasta extender los brazos.', 'No fuerces los codos en el bloqueo inferior; mantené algo de tensión. Evitá el kipping si buscás trabajo de fuerza puro.', 'Activá dorsales y bíceps imaginando que doblás la barra. Mantené el core firme para no oscilar.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('89bef2d0-4f17-572f-aeb3-b493fedcd257'::uuid, 'Hip Thrust con Barra', 'El hip thrust apoya la espalda alta en un banco y eleva la cadera con una barra sobre la pelvis hasta la extensión completa. Es el ejercicio con mayor activación directa del glúteo mayor. Apretá fuerte arriba y bajá controlando.', 'Usá una almohadilla en la barra y mantené el mentón metido para no hiperextender la lumbar. Pará la subida en la línea neutra de cadera.', 'Activá los glúteos con un par de puentes sin peso. Pensá en empujar el piso con los talones.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('ccda9680-fe88-5197-9e1b-ec60162ad24c'::uuid, 'Zancadas con Mancuernas', 'Las zancadas dan un paso adelante flexionando ambas rodillas hasta que la trasera casi toca el piso, y vuelven empujando con la pierna delantera. Desarrollan fuerza unilateral y equilibrio. Mantené el torso erguido.', 'Controlá que la rodilla delantera no sobrepase excesivamente la punta del pie. Mantené el equilibrio sin dejar caer la cadera.', 'Activá glúteo medio para estabilizar la pelvis. Hacé unos pasos sin peso para preparar el patrón.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('5cd0a1c2-15b6-535f-b9a0-a63500bbcad6'::uuid, 'Prensa de Piernas 45 Grados', 'La prensa a 45 grados empuja una plataforma cargada con los pies, flexionando y extendiendo las rodillas. Permite cargar mucho peso con menor demanda de estabilización. Bajá hasta unos 90 grados y empujá sin bloquear de golpe.', 'No bloquees las rodillas con golpe seco al final del recorrido. Mantené la zona lumbar pegada al respaldo.', 'Activá cuádriceps y glúteos colocando los pies a la altura adecuada. Empezá con peso moderado para calibrar.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('6f240294-3880-58b6-b5f5-191e0cbb1b34'::uuid, 'Curl de Piernas Tumbado', 'El curl femoral tumbado flexiona las rodillas llevando los talones hacia los glúteos contra la resistencia de la máquina. Aísla los isquiotibiales. Subí controlando y bajá resistiendo la carga.', 'Evitá levantar la cadera de la camilla para no usar impulso. No uses recorridos parciales bruscos.', 'Activá isquios con un par de repeticiones livianas. Pensá en llevar el talón al glúteo de forma controlada.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('4ddef4b4-fd6d-5a53-86ab-74774d607c97'::uuid, 'Extensión de Cuádriceps', 'La extensión de cuádriceps en máquina extiende las rodillas contra una almohadilla cargada, aislando el cuádriceps. Subí hasta casi bloquear y bajá controlado. Útil para volumen y rehabilitación.', 'Evitá el bloqueo brusco y los rebotes en la posición baja. Ajustá el respaldo para alinear la rodilla con el eje.', 'Apretá el cuádriceps en la parte alta un segundo. Activá con repeticiones livianas previas.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('eec97d7f-360e-5b9f-8fd8-1b65851d51cf'::uuid, 'Elevación de Talones de Pie', 'La elevación de talones de pie eleva el cuerpo sobre las puntas de los pies contra resistencia, trabajando los gemelos. Subí lo máximo posible y bajá estirando bien la pantorrilla. Usá rango completo.', 'Controlá el descenso para no rebotar con el tendón de Aquiles. No uses impulso de rodilla.', 'Activá la pantorrilla con un par de elevaciones lentas. Buscá la máxima contracción arriba.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('dd20f08e-0f10-535b-88a7-e19e0fb1095a'::uuid, 'Good Morning con Barra', 'El good morning coloca la barra en la espalda alta e inclina el torso hacia adelante con piernas casi rectas, hasta sentir el estiramiento de los isquios, y vuelve extendiendo la cadera. Fortalece la cadena posterior.', 'Usá cargas conservadoras y mantené la columna neutra siempre. No bajes más allá de lo que permita tu movilidad sin redondear.', 'Activá isquios y erectores con un par de repeticiones sin peso. Llevá la cadera atrás controlando.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('990c3124-f1fe-543d-bf70-6f3d072a7cb1'::uuid, 'Peso Muerto Rumano', 'El peso muerto rumano parte de pie y baja la barra deslizándola por los muslos con piernas casi rectas hasta media tibia, estirando los isquios, y vuelve extendiendo la cadera. Es referencia para la cadena posterior.', 'Mantené la barra pegada al cuerpo y la espalda neutra. No bajes más allá de tu rango sin perder la curvatura lumbar.', 'Llevá la cadera hacia atrás antes de bajar. Activá glúteos e isquios con el patrón de bisagra.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('b4119d60-2e05-59a4-80f6-dff796528e5b'::uuid, 'Press de Banca con Mancuernas', 'El press con mancuernas permite un rango de movimiento mayor que la barra y trabaja cada lado de forma independiente. Bajá las mancuernas hasta la línea del pecho y empujá juntándolas levemente arriba. Mejora la simetría y el control.', 'Controlá la fase excéntrica para no sobreestirar el hombro. Mantené las muñecas firmes y alineadas.', 'Retraé las escápulas y fijá la espalda al banco. Activá el pectoral con un par de aperturas livianas.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('4bc54bb3-480d-591e-87f9-dd3fdbfc1b15'::uuid, 'Aperturas con Mancuernas', 'Las aperturas abren los brazos en arco con los codos ligeramente flexionados, estirando el pectoral, y los cierran arriba sin chocar las mancuernas. Aíslan el pecho enfatizando el estiramiento. Movimiento controlado.', 'No bajes en exceso para no estresar la cápsula del hombro. Mantené los codos semiflexionados y fijos.', 'Pensá en abrazar un árbol al cerrar. Activá el pectoral con repeticiones lentas.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('1f0313c0-138a-52f6-be0d-1faadc1b88bc'::uuid, 'Fondos en Paralelas', 'Los fondos en paralelas sostienen el cuerpo entre dos barras y descienden flexionando los codos hasta el estiramiento del pecho, luego empujan hasta la extensión. Inclinar el torso enfatiza el pectoral inferior.', 'No bajes más allá de la movilidad cómoda del hombro. Mantené las escápulas controladas para evitar lesiones.', 'Deprimí las escápulas antes de bajar. Activá pecho y tríceps con un par de repeticiones parciales.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('0f0a0155-772e-5dfa-aa12-55c95e94d230'::uuid, 'Cruces en Polea', 'Los cruces en polea juntan las manos al frente desde dos poleas, manteniendo tensión constante sobre el pectoral en todo el rango. Variá la altura de las poleas para enfatizar distintas porciones del pecho.', 'Mantené una ligera flexión de codo constante. Controlá la vuelta para no perder tensión bruscamente.', 'Apretá el pecho un segundo al juntar las manos. Activá con un par de repeticiones livianas.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('7787fa1d-1aa9-5cf6-9b84-ae31cb67d041'::uuid, 'Press en Máquina de Pecho', 'El press en máquina empuja dos agarres hacia adelante siguiendo una trayectoria fija, ideal para enfocar el pecho con seguridad. Permite acercarse al fallo con menor riesgo. Controlá el regreso.', 'Ajustá el asiento para que los agarres queden a la altura del pecho. No bloquees los codos de golpe.', 'Retraé las escápulas contra el respaldo. Apretá el pecho al final del empuje.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('dde0348e-1d7d-5549-9b86-d5d9a0fce83f'::uuid, 'Jalón al Pecho en Polea', 'El jalón al pecho tira de una barra desde arriba hacia la parte alta del pecho, replicando el patrón de dominada con carga regulable. Desarrolla la amplitud del dorsal. Controlá la subida sin soltar la tensión.', 'Evitá inclinarte demasiado hacia atrás o usar impulso. No lleves la barra detrás de la nuca.', 'Deprimí las escápulas antes de jalar e iniciá el movimiento desde los codos.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('164a3849-888c-591d-b38c-2570c3b657bd'::uuid, 'Remo Sentado en Polea', 'El remo sentado en polea baja tira del agarre hacia el abdomen manteniendo el torso erguido, trabajando el grosor de la espalda media. Estirá bien adelante y retraé las escápulas al traccionar.', 'No uses balanceo de torso para mover la carga. Mantené la lumbar neutra durante todo el recorrido.', 'Retraé las escápulas al iniciar el tirón. Activá dorsales pensando en llevar los codos atrás.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('118edc76-2e94-5a30-a8a4-4279eb503ca3'::uuid, 'Remo con Mancuerna a una Mano', 'El remo a una mano apoya rodilla y mano en un banco y tira la mancuerna hacia la cadera, permitiendo un gran rango y trabajo unilateral. Estirá abajo y llevá el codo arriba y atrás.', 'Mantené la espalda paralela al piso y neutra. No rotes el torso para subir más peso.', 'Activá el dorsal iniciando desde el codo. Retraé la escápula en cada repetición.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('237e6532-caa4-5785-9fe8-a72814c133ac'::uuid, 'Pullover con Mancuerna', 'El pullover lleva una mancuerna desde encima del pecho hacia atrás de la cabeza en arco, estirando el dorsal y el serrato, y vuelve. Trabaja la caja torácica y la expansión del dorsal.', 'Controlá el rango hacia atrás según tu movilidad de hombro. No hiperextiendas la lumbar.', 'Activá dorsal y serrato con un par de repeticiones livianas. Mantené el core firme.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('f45871a2-b3ee-520c-8871-9e7b8d655d1d'::uuid, 'Encogimientos con Barra', 'Los encogimientos elevan los hombros hacia las orejas sosteniendo una barra, aislando el trapecio superior. Subí lo máximo posible y bajá estirando. No rotes los hombros.', 'Evitá rotar los hombros en círculos para no estresar la articulación. Mantené la cabeza neutra.', 'Apretá el trapecio un segundo arriba. Activá con un par de repeticiones controladas.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('488b86a4-82df-5440-b678-bc30df52b19d'::uuid, 'Hiperextensiones Lumbares', 'Las hiperextensiones en banco romano flexionan y extienden el torso desde la cadera, fortaleciendo la zona lumbar y la cadena posterior. Subí hasta la línea neutra sin hiperextender.', 'No hiperextiendas la columna al subir; pará en la línea recta. Controlá el descenso.', 'Activá glúteos y erectores con repeticiones sin peso. Mantené el cuello alineado.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('20769280-4b15-5d91-8a7b-daedaaa445f5'::uuid, 'Elevaciones Laterales', 'Las elevaciones laterales suben las mancuernas hacia los lados hasta la altura de los hombros con codos ligeramente flexionados, aislando el deltoides lateral. Bajá controlando sin impulso.', 'Evitá usar impulso de cadera y encoger excesivamente el trapecio. No subas por encima de la línea del hombro.', 'Activá el deltoide lateral con un par de repeticiones livianas. Liderá el movimiento con los codos.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('dd0859ee-53bb-5478-bde5-d9169a1f7bfc'::uuid, 'Press Arnold', 'El press Arnold parte con las palmas hacia el cuerpo y rota los antebrazos mientras empuja las mancuernas arriba, trabajando varias porciones del deltoides. Bajá rotando de regreso.', 'Controlá la rotación para no forzar el manguito rotador. Mantené el core firme sin arquear la lumbar.', 'Activá deltoides con elevaciones livianas. Coordiná la rotación con la subida.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('842986c8-b590-5abf-a2a2-32158a2bfb00'::uuid, 'Elevaciones Frontales', 'Las elevaciones frontales suben la mancuerna o disco al frente hasta la altura de los ojos, aislando el deltoides anterior. Bajá controlado sin balanceo.', 'No uses impulso de cadera ni subas por encima de la cabeza. Mantené el core firme.', 'Activá el deltoide anterior con repeticiones lentas. Mantené una ligera flexión de codo.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('1f6ea70d-d1e1-5e42-bdb7-0dc663a6e19c'::uuid, 'Face Pull en Polea', 'El face pull tira de una cuerda hacia la cara separando las manos al final, fortaleciendo el deltoides posterior y los rotadores externos. Excelente para la salud del hombro y la postura.', 'Usá carga moderada y priorizá la técnica sobre el peso. Mantené los codos altos.', 'Activá deltoides posterior y romboides. Pensá en separar la cuerda hacia las orejas.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('4f22ef05-0cf1-5eb2-8577-9334ecbfcf9b'::uuid, 'Press Militar con Mancuernas Sentado', 'El press de hombros sentado con mancuernas empuja las cargas desde la altura de los hombros hasta arriba con respaldo, reduciendo el impulso. Bajá controlando hasta la línea de las orejas.', 'No arquees la espalda contra el respaldo. Mantené las muñecas alineadas con los antebrazos.', 'Activá deltoides y core. Retraé ligeramente las escápulas para estabilizar.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('87f73ccf-af0d-5337-abed-dee8eee6afc6'::uuid, 'Curl con Barra', 'El curl con barra flexiona los codos llevando la barra hacia los hombros con los codos fijos a los costados, aislando el bíceps. Bajá controlando hasta extender los brazos. Es básico para el volumen de bíceps.', 'No balancees el torso para subir la barra. Mantené los codos quietos a los lados.', 'Apretá el bíceps arriba un segundo. Activá con un par de repeticiones livianas.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('d2eb9c46-4bc5-5ce3-b30c-55a6c1bd38eb'::uuid, 'Curl Martillo', 'El curl martillo flexiona los codos con agarre neutro (palmas enfrentadas), enfatizando el braquiorradial y el braquial además del bíceps. Da grosor al antebrazo y brazo. Controlá la bajada.', 'Evitá el balanceo de hombros y cadera. Mantené las muñecas firmes en neutro.', 'Activá braquiorradial y braquial. Subí sin rotar la muñeca.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('8ded18ef-2878-5752-90e3-38ac4cc5543c'::uuid, 'Curl Concentrado', 'El curl concentrado apoya el codo en el muslo sentado y flexiona el brazo aislando el bíceps con máxima contracción. Ideal para el pico del bíceps. Bajá controlando el estiramiento.', 'No uses impulso del hombro; mantené el codo fijo en el muslo. Controlá toda la fase negativa.', 'Apretá fuerte en la contracción máxima. Activá con repeticiones lentas.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('05181a1d-7e88-5d1c-aa4c-6117a8c95810'::uuid, 'Press Francés', 'El press francés acostado baja la barra EZ hacia la frente flexionando solo los codos y la extiende de nuevo, aislando el tríceps con énfasis en la cabeza larga. Mantené los codos apuntando arriba.', 'Controlá la barra cerca de la frente sin golpearla. Mantené los codos fijos sin abrirlos.', 'Activá el tríceps con un par de extensiones livianas. Estabilizá los codos antes de empezar.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('7fc37608-3a6e-5578-bb02-891c0aac4117'::uuid, 'Extensión de Tríceps en Polea con Cuerda', 'La extensión en polea con cuerda empuja hacia abajo separando los extremos al final, extendiendo los codos y aislando el tríceps. Mantené los codos pegados al cuerpo durante todo el recorrido.', 'No abras los codos ni uses el peso del cuerpo. Mantené el torso estable.', 'Apretá el tríceps separando la cuerda abajo. Activá con repeticiones controladas.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('7a935f66-8abc-5a47-88ee-b7ab27b1db34'::uuid, 'Curl de Muñeca con Barra', 'El curl de muñeca apoya los antebrazos en un banco y flexiona las muñecas elevando la barra, aislando los flexores del antebrazo y mejorando el agarre. Rango corto y controlado.', 'Usá cargas moderadas para no estresar las muñecas. Controlá el descenso completo.', 'Activá los flexores con un par de repeticiones livianas. Buscá el rango completo de muñeca.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('4a99845b-409f-5068-bf30-0c88d633f319'::uuid, 'Curl Reverso con Barra', 'El curl reverso flexiona los codos con agarre prono, enfatizando el braquiorradial y los extensores del antebrazo. Fortalece la parte superior del antebrazo y mejora el agarre. Controlá la bajada.', 'Mantené las muñecas firmes en pronación sin dejarlas caer. No uses balanceo.', 'Activá braquiorradial y extensores. Subí lento manteniendo la pronación.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('86c069fe-addd-5e92-966b-125d03d540fa'::uuid, 'Plancha Abdominal', 'La plancha sostiene el cuerpo en línea recta apoyado en antebrazos y puntas de los pies, activando isométricamente todo el core con énfasis en el transverso. Mantené la posición sin dejar caer la cadera.', 'No dejes que la cadera se hunda ni se eleve en exceso. Mantené el cuello alineado con la columna.', 'Activá el transverso metiendo el ombligo hacia adentro. Apretá glúteos para estabilizar.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('9475f6be-a53e-5c2c-aa4d-6cd451079552'::uuid, 'Crunch Abdominal', 'El crunch flexiona el tronco elevando los hombros del suelo con las rodillas flexionadas, aislando el recto abdominal en su porción superior. Subí exhalando y bajá controlando.', 'No tires del cuello con las manos. Mantené la zona lumbar en contacto con el piso.', 'Activá el recto abdominal exhalando al subir. Concentrá el movimiento en el abdomen.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('4e6844e3-2493-50f3-bcbe-a644ff152d93'::uuid, 'Elevación de Piernas Colgado', 'La elevación de piernas colgado de la barra eleva las piernas rectas o las rodillas hacia el pecho, trabajando el abdomen inferior y los flexores de cadera. Controlá la bajada sin balanceo.', 'Evitá el balanceo del cuerpo para usar impulso. Controlá tanto la subida como la bajada.', 'Activá el abdomen inferior antes de elevar. Deprimí las escápulas para estabilizar el cuerpo.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('74dc11e0-3d4e-5ae3-b092-2c3949617f50'::uuid, 'Russian Twist', 'El russian twist sentado con el torso inclinado rota el tronco de lado a lado, opcionalmente con peso, trabajando los oblicuos. Mantené el core firme y los pies elevados para mayor dificultad.', 'Controlá la rotación desde el tronco, no solo con los brazos. Mantené la espalda recta sin redondear.', 'Activá los oblicuos rotando de forma controlada. Mantené el abdomen contraído.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('730764c2-8a89-5a5f-8cab-0174b8337f04'::uuid, 'Rueda Abdominal', 'La rueda abdominal rueda hacia adelante extendiendo el cuerpo desde las rodillas y vuelve contrayendo el core, demandando gran fuerza del abdomen y antirotación. Avanzá solo hasta donde controles.', 'No dejes que la lumbar se arquee al extender. Avanzá progresivamente en el rango.', 'Activá el core antes de rodar. Mantené la cadera ligeramente metida.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('6ffe24cb-d836-5c6e-8353-42d20a5eed7a'::uuid, 'Dead Bug', 'El dead bug acostado extiende brazo y pierna opuestos manteniendo la zona lumbar pegada al suelo, entrenando la estabilidad del core. Movimiento lento y controlado con respiración coordinada.', 'Mantené la lumbar pegada al piso en todo momento. No extiendas más allá de lo que puedas controlar.', 'Activá el transverso antes de mover las extremidades. Coordiná la respiración con el movimiento.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('c51195fe-0bef-5c29-a0ee-ed0793f59999'::uuid, 'Arranque (Snatch)', 'El arranque levanta la barra desde el suelo hasta encima de la cabeza en un solo movimiento explosivo con agarre ancho. Combina un tirón potente, una recepción en sentadilla profunda y la estabilización overhead. Es el levantamiento olímpico más técnico.', 'Dominá la técnica con carga ligera antes de añadir peso. Mantené la barra cerca del cuerpo y la columna neutra en el tirón.', 'Movilizá hombros, muñecas y tobillos a fondo. Activá la cadena posterior con tirones livianos antes de la serie.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('863c1df1-20ba-5af3-888a-e02871ac42fd'::uuid, 'Cargada (Clean)', 'La cargada lleva la barra del suelo a los hombros en posición de recepción frontal, mediante un tirón explosivo y una sentadilla. Es la base del clean and jerk y desarrolla potencia de cadera.', 'Mantené la barra pegada al cuerpo durante el tirón. Recibí con los codos altos y la columna neutra.', 'Activá glúteos e isquios con tirones desde la rodilla. Movilizá muñecas para la recepción frontal.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('53f1307d-fdac-57b2-ba90-9754434145d2'::uuid, 'Envión (Jerk)', 'El envión impulsa la barra desde los hombros hasta overhead mediante un empuje de piernas y una recepción con un pie adelante (split jerk). Permite mover más peso que un press estricto.', 'Coordiná el impulso de piernas con el empuje de brazos. Estabilizá la barra sobre la cabeza con el core firme.', 'Activá piernas y hombros con dip-drives livianos. Practicá el split sin carga primero.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('dcf2334c-a1e1-532e-9b14-33a053e029c5'::uuid, 'Clean and Jerk', 'El clean and jerk combina la cargada y el envión: lleva la barra del suelo a los hombros y luego overhead. Es uno de los dos levantamientos de competición olímpica y demanda potencia y técnica completas.', 'Trabajá cada fase por separado antes de unirlas. Mantené la columna neutra y la barra cerca del cuerpo.', 'Movilizá todo el cuerpo y activá la cadena posterior. Hacé repeticiones técnicas con barra vacía.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('f7350026-d54f-50f3-8ec5-06ea3ee138ae'::uuid, 'Sentadilla Frontal', 'La sentadilla frontal apoya la barra sobre los deltoides anteriores con los codos altos, manteniendo el torso muy vertical. Enfatiza el cuádriceps y el core, y transfiere a la recepción del clean.', 'Mantené los codos altos para que la barra no caiga. Cuidá la muñeca y la columna neutra.', 'Movilizá muñecas y dorsal para la posición de rack. Activá el core antes de descender.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('3c0092f9-2851-59ee-9ed5-23a3a74c0991'::uuid, 'Tirón de Arranque (Snatch Pull)', 'El tirón de arranque ejecuta la primera y segunda fase del snatch sin la recepción, enfatizando la potencia del tirón y la extensión de cadera con agarre ancho. Acelerá fuerte en la extensión.', 'Mantené la espalda neutra y la barra cerca del cuerpo. No redondees la lumbar en el despegue.', 'Activá la cadena posterior con tirones desde la rodilla. Generá tensión antes de despegar.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('eb77f747-97b5-568c-b9c1-422a47b3c809'::uuid, 'Power Clean', 'El power clean recibe la barra en los hombros en una posición de cuarto de sentadilla, sin bajar a la sentadilla completa. Desarrolla potencia explosiva y es muy usado en preparación deportiva.', 'Recibí con los codos rápidos y altos. Mantené la columna neutra durante el tirón explosivo.', 'Activá glúteos e isquios con tirones livianos. Practicá la recepción alta con barra vacía.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('f1e7e8e7-ff80-5964-bd8f-977afa3a1ae5'::uuid, 'Overhead Squat', 'La sentadilla overhead sostiene la barra con los brazos extendidos sobre la cabeza mientras se realiza una sentadilla completa. Demanda movilidad y estabilidad extremas de hombro, cadera y tobillo.', 'Requiere buena movilidad; empezá con un palo o barra vacía. Mantené la barra estable sobre la línea media.', 'Movilizá hombros, tobillos y cadera a fondo. Activá el core y los estabilizadores del hombro.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('a806e2c8-820f-5dcb-b720-49dbb9a5d6c7'::uuid, 'Push Press', 'El push press empuja la barra desde los hombros hasta overhead usando un impulso inicial de piernas. Permite cargar más que un press estricto y entrena la transferencia de fuerza pierna-brazo.', 'Coordiná el dip de piernas con el empuje. No arquees la lumbar al bloquear arriba.', 'Activá piernas y hombros con dip-drives livianos. Mantené el core firme antes de impulsar.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('9a152e8b-aa17-5053-b010-d079995c1383'::uuid, 'Thruster', 'El thruster combina una sentadilla frontal con un push press en un movimiento fluido: desde el fondo de la sentadilla, la extensión de cadera impulsa la barra overhead. Es uno de los movimientos más demandantes del crossfit.', 'Mantené los codos altos en la sentadilla y el core firme. No arquees la lumbar al empujar arriba.', 'Activá piernas y hombros con repeticiones livianas. Movilizá muñecas para el rack frontal.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('67d50929-5b29-59b1-98cb-35043b9e0e7f'::uuid, 'Burpee', 'El burpee baja a posición de plancha, hace una flexión, recoge los pies y salta con las manos arriba. Es un ejercicio de cuerpo completo y alta demanda cardiovascular, pilar del acondicionamiento metabólico.', 'Cuidá la zona lumbar al caer en plancha; bajá controlado. Amortiguá la recepción del salto con las rodillas.', 'Activá el core y entrá en calor con saltos suaves. Mantené un ritmo sostenible.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('9043fea4-fecc-5670-a164-6b1c9a767ed6'::uuid, 'Wall Ball', 'El wall ball realiza una sentadilla y lanza un balón medicinal a un objetivo en la pared, recibiéndolo y encadenando repeticiones. Combina potencia de piernas, empuje y resistencia cardiovascular.', 'Mantené la espalda neutra al recibir el balón. Atrapalo con los brazos amortiguando hacia la próxima sentadilla.', 'Activá piernas y hombros con sentadillas y empujes livianos. Calibrá la distancia al objetivo.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('46a63d3f-b3e4-530f-ba93-90b9f933b6d6'::uuid, 'Box Jump', 'El box jump salta sobre un cajón desde el suelo extendiendo cadera, rodilla y tobillo, y baja controlado. Desarrolla potencia explosiva del tren inferior y se usa en circuitos metabólicos.', 'Bajá del cajón con control, idealmente paso a paso, para cuidar el tendón de Aquiles. Aterrizá con rodillas flexionadas.', 'Activá glúteos y cuádriceps con saltos suaves. Calibrá la altura del cajón a tu nivel.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('42dbe453-0ce4-5da4-9015-f3d4c2f90551'::uuid, 'Kettlebell Swing', 'El kettlebell swing impulsa la pesa rusa desde entre las piernas hasta la altura del pecho mediante una potente extensión de cadera (bisagra), no con los brazos. Desarrolla potencia de cadera y resistencia.', 'Mové la pesa con la cadera, no con la espalda baja ni los hombros. Mantené la columna neutra en la bisagra.', 'Activá glúteos e isquios con bisagras sin peso. Generá el impulso desde la cadera.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('d81d203d-10fd-524a-8a4c-aa8e7319a18b'::uuid, 'Muscle Up en Anillas', 'El muscle up combina una dominada explosiva con una transición a fondo sobre las anillas, terminando en soporte con los brazos extendidos. Es un movimiento avanzado de gimnasia en crossfit.', 'Dominá la dominada estricta y el fondo antes de intentarlo. Controlá la transición para no estresar el hombro.', 'Activá dorsal, pecho y tríceps. Practicá transiciones con asistencia de banda.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('96a0462f-ff99-5ca5-8189-2cfa62c5eb59'::uuid, 'Toes to Bar', 'El toes to bar cuelga de la barra y lleva las puntas de los pies a tocarla mediante una flexión potente del abdomen y la cadera. Entrena el core y la coordinación del kipping.', 'Controlá el balanceo para no perder el agarre. Protegé la lumbar evitando la hiperextensión en el back swing.', 'Activá el abdomen y deprimí las escápulas. Practicá el ritmo de kipping sin tocar la barra.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('3aa66420-1962-558f-bf78-b729d61ce60e'::uuid, 'Double Under', 'El double under pasa la soga dos veces por salto, exigiendo timing, coordinación y resistencia de pantorrillas. Es un clásico del acondicionamiento en crossfit que eleva mucho la frecuencia cardíaca.', 'Saltá con rebotes bajos y eficientes para cuidar las articulaciones. Mantené los codos cerca del cuerpo.', 'Activá pantorrillas con saltos simples. Coordiná el giro de muñeca con el salto.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('7f6f7b2c-9172-5767-ad00-78d233f05c1c'::uuid, 'Handstand Push Up', 'El handstand push up baja y empuja el cuerpo en posición de parada de manos contra la pared, trabajando el empuje vertical con el peso corporal. Es un referente de fuerza de hombros en crossfit.', 'Asegurá un buen apoyo en pared y protegé el cuello al bajar. Controlá el descenso hasta tocar suavemente.', 'Activá hombros y tríceps con pikes. Verificá la estabilidad de muñecas y el espacio.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('883e317c-f6cc-5b47-9024-c15fce7bc1ce'::uuid, 'Remo en Ergómetro', 'El remo en ergómetro reproduce la remada combinando un empuje de piernas, una apertura de cadera y un tirón de brazos en secuencia. Es un ejercicio cardiovascular de cuerpo completo de bajo impacto.', 'Seguí la secuencia piernas-cadera-brazos y volvé en orden inverso. Mantené la espalda neutra sin redondear.', 'Activá piernas y espalda con remadas suaves. Ajustá el damper a un nivel cómodo.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('b258ce08-f6fa-5d04-8797-54a9effb85b6'::uuid, 'Assault Bike', 'La assault bike pedalea y empuja los brazos simultáneamente, generando una resistencia que aumenta con el esfuerzo. Es de las herramientas más intensas para el acondicionamiento metabólico.', 'Ajustá el asiento para no hiperextender la rodilla. Comenzá a ritmo moderado para calibrar la intensidad.', 'Entrá en calor con un par de minutos suaves. Coordiná brazos y piernas en cada pedalada.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('b5d1dd0a-3085-52bb-a6aa-e792c458bfdf'::uuid, 'Snatch con Mancuerna', 'El snatch con mancuerna lleva una sola pesa desde el suelo o entre las piernas hasta overhead en un movimiento explosivo y unilateral. Muy usado en WODs por su demanda de potencia y coordinación.', 'Mantené la columna neutra y la mancuerna cerca del cuerpo. Estabilizá el hombro en el bloqueo overhead.', 'Activá cadera y hombro con repeticiones livianas. Alterná brazos para equilibrar.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('40e811b0-7365-586a-95b7-607375943d72'::uuid, 'Clean and Jerk con Mancuernas', 'El clean and jerk con mancuernas lleva las pesas del suelo a los hombros y luego overhead, replicando el patrón olímpico con mancuernas. Permite trabajar potencia con menor exigencia técnica que la barra.', 'Coordiná la recepción de la cargada con los codos altos. Estabilizá ambas mancuernas overhead.', 'Activá piernas y hombros con dip-drives. Practicá la transición con poco peso.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('58542c25-2636-56f7-b322-388fb19f4e57'::uuid, 'Farmer Carry', 'El farmer carry camina sosteniendo cargas pesadas en cada mano, desafiando el agarre, el trapecio y la estabilidad del core. Desarrolla fuerza funcional y resistencia muscular general.', 'Mantené el torso erguido y los hombros atrás. No dejes que la carga te incline hacia un lado.', 'Activá el agarre y el core antes de levantar. Caminá con pasos cortos y controlados.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('adcc38f6-98d0-5d03-89d6-a613c8df1ac1'::uuid, 'Devil Press', 'El devil press combina un burpee sobre dos mancuernas con un snatch hasta overhead, encadenando flexión de pecho y empuje explosivo. Es uno de los movimientos más exigentes del crossfit metabólico.', 'Cuidá la lumbar al bajar y al levantar las mancuernas. Mantené la columna neutra en el swing hacia arriba.', 'Activá pecho, hombros y cadera. Empezá con cargas livianas para dominar el patrón.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('1c0ecd44-65ee-5aba-a81c-2bf60dd106db'::uuid, 'Jab al Saco', 'El jab es el golpe recto del brazo adelantado, que sale directo desde la guardia rotando ligeramente el puño al impactar. Es el golpe más usado en boxeo para medir distancia y abrir la ofensiva. Trabajá velocidad y retorno rápido a la guardia.', 'Vendá las manos y usá guantes adecuados para proteger muñecas y nudillos. Mantené la muñeca firme al impactar.', 'Activá hombros y core con sombra liviana. Soltá los golpes relajado y exhalá en cada impacto.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('eaed102c-224d-5dc5-8c94-4863b2488450'::uuid, 'Cross (Recto de Derecha) al Saco', 'El cross es el recto de la mano trasera, que gana potencia al rotar la cadera y el pie trasero transfiriendo fuerza desde el suelo. Es uno de los golpes más potentes del boxeo. Coordiná el giro de cadera con la extensión del brazo.', 'Protegé las manos con vendas y guantes. No bloquees el codo de golpe al extender.', 'Activá la cadena rotando cadera y pie trasero. Mantené la otra mano en guardia.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('221d5c19-58ec-5344-b78f-f88dd9028ffa'::uuid, 'Hook (Gancho) al Saco', 'El hook es un golpe lateral con el brazo flexionado en ángulo recto que gira con la cadera y los pies para impactar de costado. Genera potencia desde la rotación del tronco. Mantené el codo a la altura del puño.', 'Cuidá la muñeca y mantené el puño firme al impactar. No sobreextiendas el hombro.', 'Activá oblicuos y cadera con rotaciones de tronco. Pivoteá el pie al golpear.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('27922c92-9cff-5792-9c33-d97c609581bb'::uuid, 'Uppercut al Saco', 'El uppercut es un golpe ascendente que sube desde abajo flexionando ligeramente las piernas y extendiéndolas con la rotación de cadera. Apunta al mentón o al cuerpo. Generá la fuerza desde las piernas y el tronco.', 'No bajes demasiado la guardia al cargar el golpe. Mantené la muñeca firme en la trayectoria ascendente.', 'Activá piernas y core con sentadillas ligeras. Coordiná el impulso de piernas con el golpe.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('b85fbc4a-bfbc-5d04-8dbb-1156976da0a7'::uuid, 'Trabajo de Sombra (Shadow Boxing)', 'El shadow boxing practica combinaciones de golpes y desplazamientos sin saco, frente al espejo o al aire, perfeccionando técnica, ritmo y juego de pies. Es fundamental para el calentamiento y la técnica en boxeo.', 'Mantené las articulaciones algo flexionadas y no bloquees los codos en el aire. Cuidá el equilibrio en los desplazamientos.', 'Activá el cuerpo con movilidad de hombros y cadera. Empezá lento y subí el ritmo gradualmente.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('08effdfa-8440-5210-8221-a26f86d9dbd9'::uuid, 'Salto a la Comba (Boxeo)', 'El salto a la comba es base del acondicionamiento del boxeador: mejora el juego de pies, la coordinación, el ritmo y la resistencia cardiovascular. Saltá con rebotes bajos sobre las puntas de los pies.', 'Saltá con rebotes bajos para cuidar tobillos y rodillas. Mantené los hombros relajados.', 'Activá pantorrillas con saltos suaves. Coordiná el giro de muñeca con el salto.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('bf2bf00c-ec29-55cd-b149-101968ceb09c'::uuid, 'Esquivas con Cuerda Horizontal', 'Las esquivas (slips y bobbing) practican el movimiento de cabeza y tronco para evitar golpes flexionando las rodillas y rotando levemente. Mejoran la defensa y el trabajo de piernas. Mantené la guardia en todo momento.', 'No bajes la guardia al esquivar. Cuidá las rodillas al flexionar repetidamente.', 'Activá piernas y core con sentadillas ligeras. Mantené la vista al frente.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('8e5225f3-6246-5295-85ad-a39ab157e295'::uuid, 'Golpeo de Manoplas (Pad Work)', 'El trabajo de manoplas golpea las paletas que sostiene un entrenador, encadenando combinaciones con precisión, timing y potencia. Es clave para integrar técnica, reacción y acondicionamiento en boxeo.', 'Vendá y enguantá las manos correctamente. Mantené la muñeca firme en cada impacto.', 'Activá hombros y core con sombra. Soltá las combinaciones relajado y respirando.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('76e14d32-e4b6-56a6-8a25-4f221747c2ce'::uuid, 'Golpeo al Saco Pesado', 'El saco pesado permite descargar potencia real en golpes y combinaciones, desarrollando fuerza de impacto, resistencia y técnica bajo fatiga. Variá golpes, ángulos y desplazamientos por rounds.', 'Vendá bien las manos y no golpees con la muñeca floja. Mantené la distancia para no impactar con el antebrazo.', 'Activá todo el cuerpo con sombra previa. Exhalá en cada golpe y volvé siempre a la guardia.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('be8a31dc-7eb9-5b83-ac44-e6eb240950dc'::uuid, 'Golpeo al Pera Loca (Doble End Bag)', 'La pera loca es una bola sujeta por arriba y abajo con elásticos que rebota de forma impredecible, entrenando la precisión, el timing y los reflejos. Mejora la coordinación ojo-mano del boxeador.', 'Mantené la guardia alta porque la pera rebota rápido hacia la cara. Cuidá las muñecas en los impactos.', 'Activá hombros y reflejos con golpes suaves. Concentrate en el timing antes que en la potencia.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('3db9876a-78ed-57c7-aee5-82f74c2ef0a8'::uuid, 'Trabajo de Cuello (Neck Bridge Boxeo)', 'El trabajo de cuello fortalece la musculatura cervical para absorber impactos y reducir el riesgo de conmoción, mediante movimientos isométricos y de rango controlado. Es esencial en deportes de contacto.', 'Trabajá con rango controlado y sin cargas bruscas. Progresá lentamente para no lesionar las cervicales.', 'Activá el cuello con movimientos suaves en todas las direcciones. Mantené la respiración constante.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('d385f1dc-697f-565a-82f4-93f323b51a40'::uuid, 'Salto al Cajón con Caída (Depth Jump)', 'El depth jump baja de un cajón y, al tocar el suelo, salta inmediatamente lo más alto posible, entrenando el ciclo estiramiento-acortamiento y la potencia reactiva. Es avanzado y propio del entrenamiento atlético.', 'Requiere base de fuerza previa; usá alturas moderadas. Aterrizá suave con rodillas flexionadas para proteger las articulaciones.', 'Activá el sistema nervioso con saltos submáximos. Buscá el mínimo tiempo de contacto con el suelo.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('0b1689df-d643-5121-8da2-b5ceb6d9a0f6'::uuid, 'Salto Vertical (Squat Jump)', 'El squat jump desciende a media sentadilla y salta verticalmente con máxima potencia, extendiendo cadera, rodilla y tobillo. Desarrolla la potencia explosiva del tren inferior para muchos deportes.', 'Aterrizá con las rodillas flexionadas para amortiguar. No redondees la espalda al descender.', 'Activá glúteos y cuádriceps con sentadillas. Buscá la máxima altura en cada salto.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('0e47b5af-39d1-50f2-bd75-af8f66fa6734'::uuid, 'Salto en Largo sin Carrera (Broad Jump)', 'El broad jump salta hacia adelante la mayor distancia posible desde parado, proyectando la cadera y los brazos. Mide y entrena la potencia horizontal, relevante para sprints y deportes de campo.', 'Aterrizá con las rodillas flexionadas y el control del torso. Evitá caer con las piernas rígidas.', 'Activá la cadena posterior con saltos suaves. Coordiná el balanceo de brazos con el despegue.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('4819a310-910d-51f6-a39b-22d1924d6994'::uuid, 'Sprint en Cuesta', 'El sprint en cuesta corre a máxima intensidad sobre una pendiente, aumentando la demanda de potencia y reduciendo el impacto frente al sprint en llano. Mejora la aceleración y la fuerza de zancada.', 'Entrá en calor a fondo antes de los sprints máximos. Bajá caminando para recuperar y cuidar los isquios.', 'Activá glúteos e isquios con skipping. Proyectá el cuerpo con zancadas potentes.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('ff25db31-cf71-50ee-a285-2b45af25253f'::uuid, 'Skipping Alto', 'El skipping alto eleva las rodillas de forma rápida y alternada coordinando los brazos, mejorando la técnica de carrera, la frecuencia de zancada y el acondicionamiento. Es un clásico del calentamiento atlético.', 'Mantené el tronco erguido sin echarte atrás. Apoyá sobre el metatarso para cuidar las articulaciones.', 'Activá flexores de cadera y pantorrillas. Coordiná brazos y piernas con ritmo.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('9fd5eb1f-1102-5905-859c-23286f753574'::uuid, 'Flexiones de Brazos', 'La flexión baja y empuja el cuerpo en plancha apoyado en manos y pies, trabajando pecho, tríceps y hombros con el peso corporal. Es un ejercicio fundamental de empuje sin equipamiento. Mantené el cuerpo en línea.', 'No dejes caer la cadera ni eleves los glúteos. Mantené los codos a unos 45 grados del torso.', 'Activá pecho y core antes de bajar. Mantené la línea recta de la cabeza a los talones.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('7fffff3a-c8ac-563d-86a0-f125b21b1dc1'::uuid, 'Flexiones Diamante', 'La flexión diamante junta las manos formando un triángulo bajo el pecho, enfatizando el tríceps. Bajá controlando hasta rozar las manos con el pecho y empujá. Es excelente para el desarrollo del tríceps con peso corporal.', 'Mantené los codos cerca del cuerpo. No dejes caer la cadera durante el movimiento.', 'Activá tríceps y core. Mantené la línea recta del cuerpo en todo el rango.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('9391b544-e109-5ef0-a78c-79da3b3f0f65'::uuid, 'Sentadilla con Peso Corporal', 'La sentadilla libre desciende flexionando cadera y rodillas con el peso del cuerpo y vuelve extendiendo, siendo la base del patrón de sentadilla. Ideal para calentar, aprender la técnica y trabajar resistencia.', 'Mantené los talones apoyados y la espalda neutra. No dejes que las rodillas colapsen hacia adentro.', 'Activá glúteos y cuádriceps con repeticiones lentas. Mantené el pecho alto.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('ff2c7b9d-f47f-50fb-95a2-4199590e54e9'::uuid, 'Fondo de Tríceps en Banco', 'El fondo en banco apoya las manos en un banco detrás del cuerpo y baja flexionando los codos para luego empujar, trabajando el tríceps con el peso corporal. Mantené los codos apuntando hacia atrás.', 'No bajes en exceso para no estresar el hombro. Mantené los codos cerca del cuerpo.', 'Activá tríceps con repeticiones parciales. Mantené la espalda cerca del banco.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('927ef7f8-d4a6-515f-a1ea-a9b7ab8d63aa'::uuid, 'Plancha Lateral', 'La plancha lateral sostiene el cuerpo de costado apoyado en un antebrazo y el canto del pie, activando los oblicuos y el glúteo medio de forma isométrica. Mantené la cadera elevada y el cuerpo en línea.', 'No dejes caer la cadera hacia el suelo. Mantené el cuello alineado con la columna.', 'Activá oblicuos y glúteo medio antes de elevar. Apretá el core para mantener la línea.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('795e735a-9f1c-5420-86c5-c6a33fa8f945'::uuid, 'Superman', 'El superman acostado boca abajo eleva simultáneamente brazos y piernas extendiendo la espalda, fortaleciendo los erectores y la cadena posterior. Subí controlando y mantené brevemente la contracción.', 'No hiperextiendas el cuello; mantené la mirada al piso. Subí de forma controlada sin tirones.', 'Activá glúteos y erectores. Elevá brazos y piernas a la vez con control.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('f721cac0-a409-56e7-895e-c56a9d8ca1cd'::uuid, 'Pistol Squat', 'El pistol squat es una sentadilla a una pierna con la otra extendida al frente, demandando fuerza unilateral, equilibrio y movilidad. Es un ejercicio avanzado de calistenia para el tren inferior.', 'Requiere movilidad y fuerza; usá apoyo o asistencia al inicio. Controlá el descenso para proteger la rodilla.', 'Activá cuádriceps y glúteos con sentadillas. Mejorá la movilidad de tobillo previamente.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('0ef777db-5eb5-51f5-a258-fc8be8738c57'::uuid, 'Dead Hang en Barra', 'El dead hang cuelga de la barra con los brazos extendidos manteniendo la posición el mayor tiempo posible, fortaleciendo el agarre, los antebrazos y la salud del hombro. Es base para escalada y dominadas.', 'Mantené los hombros activos, no completamente relajados. Progresá el tiempo de forma gradual.', 'Activá el agarre y deprimí levemente las escápulas. Respirá de forma constante.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('f2ea8abe-2658-5ebd-ba91-1b316941a932'::uuid, 'Dominadas con Toalla', 'Las dominadas con toalla agarran una toalla sobre la barra en lugar de la barra misma, aumentando enormemente la demanda del agarre y los antebrazos. Es un favorito de escaladores y luchadores.', 'Asegurá la toalla firmemente sobre la barra. Bajá controlado para cuidar codos y hombros.', 'Activá el agarre apretando fuerte la toalla. Deprimí las escápulas antes de tirar.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('e8e0b563-6b7d-5c20-b6ad-9182e55516cf'::uuid, 'Trabajo en Hangboard', 'El hangboard cuelga de pequeñas regletas o agarres de distintos tamaños, desarrollando fuerza específica de dedos y agarre para la escalada. Trabajá con tiempos y agarres progresivos.', 'Calentá los dedos a fondo antes de cargar; es exigente para las poleas de los dedos. Evitá agarres de máxima dificultad sin base.', 'Activá antebrazos y dedos con colgadas suaves. Progresá agarres de forma conservadora.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('e317d4fa-8fca-5b73-af53-042894676c79'::uuid, 'Turkish Get Up', 'El turkish get up pasa de estar acostado a de pie sosteniendo una pesa overhead, a través de una secuencia de transiciones controladas. Entrena estabilidad de hombro, core y coordinación de cuerpo completo.', 'Aprendé la secuencia sin peso o con carga muy ligera. Mantené la vista en la pesa y el brazo siempre vertical.', 'Activá hombro y core. Practicá cada transición lentamente antes de encadenar.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('976cc469-7dea-574e-befb-bceb94679e60'::uuid, 'Goblet Squat', 'El goblet squat sostiene una pesa rusa o mancuerna contra el pecho mientras se hace una sentadilla, lo que ayuda a mantener el torso erguido y enseña el patrón. Excelente para principiantes y para calentar.', 'Mantené los codos dentro de las rodillas y la espalda neutra. No dejes caer el pecho.', 'Activá cuádriceps y core. Mantené la pesa pegada al cuerpo durante todo el rango.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('f4fc0d44-c0ea-59d6-bbf1-bf67ff192fcb'::uuid, 'Kettlebell Clean and Press', 'El clean and press con kettlebell lleva la pesa del suelo al rack frontal y luego overhead, combinando potencia de cadera y empuje de hombro. Es un movimiento funcional completo y unilateral.', 'Controlá la cargada para que la pesa no golpee el antebrazo. Estabilizá el hombro en el bloqueo overhead.', 'Activá cadera y hombro con limpias livianas. Coordiná el impulso con el empuje.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('00ed9c73-b776-555d-aed9-aff581d0bb27'::uuid, 'Renegade Row', 'El renegade row parte en plancha sobre dos mancuernas y rema una hacia la cadera mientras el core resiste la rotación. Combina trabajo de espalda con estabilidad antirotación intensa.', 'Mantené la cadera estable sin rotarla al remar. Abrí los pies para mayor base si lo necesitás.', 'Activá core y dorsal. Apretá el abdomen para evitar el balanceo de cadera.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('63ad3551-0e23-588a-bb47-353311dd0700'::uuid, 'Curl en Banco Inclinado', 'El curl en banco inclinado sentado deja los brazos colgar atrás del torso, estirando el bíceps al máximo antes de flexionar. Enfatiza la cabeza larga del bíceps. Controlá la fase negativa por completo.', 'No balancees los hombros para subir. Mantené los codos atrás y fijos durante el movimiento.', 'Activá el bíceps en el estiramiento. Subí de forma controlada y apretá arriba.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('5f865b48-7507-5d8c-8225-99979f30f7a8'::uuid, 'Curl Predicador', 'El curl predicador apoya los brazos sobre un soporte inclinado, aislando el bíceps e impidiendo el impulso. Enfatiza la cabeza corta. Bajá controlando sin extender bruscamente el codo.', 'No extiendas el codo de golpe en la bajada para proteger el tendón. Mantené los brazos firmes en el soporte.', 'Activá el bíceps con repeticiones livianas. Controlá toda la fase excéntrica.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('6b2c2270-71ad-58ed-9f50-b9f4d0294e72'::uuid, 'Patada de Tríceps (Kickback)', 'El kickback inclina el torso y extiende el codo hacia atrás con una mancuerna, aislando el tríceps con énfasis en la contracción final. Mantené el brazo paralelo al torso y solo movés el antebrazo.', 'No balancees el hombro; mantené el brazo fijo. Usá cargas moderadas para mantener la técnica.', 'Apretá el tríceps al extender completamente. Activá con repeticiones controladas.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('281192eb-7d89-5c2b-9f07-d98ac8a5e796'::uuid, 'Elevación de Talones Sentado', 'La elevación sentado flexiona las rodillas y eleva los talones contra una almohadilla cargada sobre los muslos, enfocando el sóleo de la pantorrilla. Subí al máximo y bajá estirando bien.', 'Controlá el descenso para estirar el sóleo sin rebotar. Ajustá el peso de forma progresiva.', 'Activá la pantorrilla con repeticiones lentas. Buscá el rango completo.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('e606f9d5-04c8-55ca-ad54-87f4a02e65ba'::uuid, 'Abducción de Cadera en Máquina', 'La abducción separa las piernas contra la resistencia de la máquina, aislando el glúteo medio. Es útil para la estabilidad de cadera y la estética del glúteo. Controlá la vuelta sin soltar la tensión.', 'Evitá usar impulso del torso. Controlá tanto la apertura como el cierre.', 'Activá el glúteo medio con repeticiones livianas. Apretá en la máxima apertura.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('0c3ebd34-59e1-5d36-9e6d-c60dccb68f49'::uuid, 'Aducción de Cadera en Máquina', 'La aducción junta las piernas contra la resistencia de la máquina, aislando los aductores del muslo interno. Mejora la estabilidad de cadera y previene lesiones de ingle. Controlá la apertura.', 'No abras más allá de tu rango cómodo. Controlá la fase de regreso.', 'Activá los aductores con repeticiones lentas. Apretá al juntar las piernas.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('a801cfef-76a8-5856-af70-9979ddff1f4e'::uuid, 'Crunch en Polea Alta', 'El crunch en polea alta (arrodillado) flexiona el tronco hacia abajo contra la resistencia de la polea con una cuerda, permitiendo cargar el abdomen progresivamente. Concentrá el movimiento en el recto abdominal.', 'No tires con los brazos; el movimiento viene del abdomen. Mantené la cadera fija.', 'Activá el recto abdominal exhalando al flexionar. Mantené la tensión en todo el rango.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('96f9879a-caef-55cf-b704-2627b9265e09'::uuid, 'Hollow Hold', 'El hollow hold acostado eleva piernas y hombros del suelo manteniendo la zona lumbar pegada, creando una posición isométrica de tensión total del core. Es base de la gimnasia y el crossfit.', 'Mantené la lumbar pegada al piso; si se despega, elevá más las piernas. No contengas la respiración.', 'Activá el transverso antes de elevar. Mantené la tensión sin perder la forma.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('a133417e-345d-5982-98c7-f6f8a0f5f857'::uuid, 'Face Pull con Banda Elástica', 'El face pull con banda tira de una banda elástica hacia la cara separando las manos, fortaleciendo el deltoides posterior y los rotadores con resistencia variable. Ideal para casa y prehabilitación.', 'Mantené los codos altos y la carga moderada. Priorizá la técnica sobre la tensión de la banda.', 'Activá deltoides posterior y romboides. Separá la banda hacia las orejas.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('0a5133a6-f25d-53b1-bff6-3fcc80d4c267'::uuid, 'Remo Invertido', 'El remo invertido cuelga el cuerpo bajo una barra fija y tira del pecho hacia ella manteniendo el cuerpo recto, trabajando la espalda con el peso corporal. Variá la inclinación para regular la dificultad.', 'Mantené el cuerpo en línea sin dejar caer la cadera. Retraé las escápulas en cada tirón.', 'Activá dorsal y romboides. Iniciá el tirón desde los codos.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('29eb63c7-3d7d-596a-8eea-152a23c86e34'::uuid, 'Bird Dog', 'El bird dog en cuadrupedia extiende brazo y pierna opuestos manteniendo la columna estable, entrenando la coordinación y la estabilidad lumbo-pélvica. Es excelente para la salud de la espalda.', 'Mantené la columna neutra sin rotar la cadera. Extendé solo hasta donde controles la estabilidad.', 'Activá el core antes de extender. Coordiná brazo y pierna con control.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('808ffb94-089f-56b2-b367-db0c08674220'::uuid, 'Encogimientos con Mancuernas', 'Los encogimientos con mancuernas elevan los hombros hacia las orejas sosteniendo una mancuerna en cada mano, aislando el trapecio superior con mayor rango que la barra. Subí y apretá arriba.', 'No rotes los hombros en círculos. Mantené el cuello relajado y la mirada al frente.', 'Apretá el trapecio un segundo arriba. Activá con repeticiones controladas.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('7bbbefa2-a195-5967-99ed-34020c0503c2'::uuid, 'Press Cerrado en Banca', 'El press de banca con agarre cerrado acerca las manos a la anchura de hombros, trasladando gran parte del trabajo al tríceps además del pecho. Mantené los codos cerca del cuerpo al bajar.', 'No cierres tanto el agarre como para estresar las muñecas. Mantené los codos pegados al torso.', 'Activá tríceps y pecho. Bajá controlando hacia la parte baja del pecho.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('b5da1390-d7b7-5cae-8e58-df48e5f17557'::uuid, 'Sentadilla Búlgara', 'La sentadilla búlgara apoya el pie trasero elevado en un banco y desciende con la pierna delantera, intensificando el trabajo unilateral de cuádriceps y glúteo. Desarrolla fuerza, equilibrio y corrige asimetrías.', 'Mantené el torso estable y la rodilla delantera alineada con el pie. No dejes caer la cadera hacia un lado.', 'Activá glúteo y cuádriceps con repeticiones sin peso. Buscá el equilibrio antes de cargar.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('72428737-44c5-5699-a839-dfb4118b0ea1'::uuid, 'Sentadilla Hack en Máquina', 'La sentadilla hack en máquina apoya la espalda en un respaldo inclinado y empuja la plataforma con los pies, enfocando el cuádriceps con la columna protegida. Bajá controlado y empujá sin bloquear de golpe.', 'Mantené la espalda pegada al respaldo. No bloquees las rodillas bruscamente arriba.', 'Activá el cuádriceps con repeticiones livianas. Colocá los pies según el énfasis buscado.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('6e5fbdaf-6866-5997-b92a-e1928e049124'::uuid, 'Peso Muerto con Trap Bar', 'El peso muerto con barra hexagonal se realiza de pie dentro de la barra, con agarre neutro a los lados, lo que reduce la demanda lumbar y reparte la carga entre piernas y espalda. Ideal para aprender el patrón.', 'Mantené la espalda neutra y empujá el piso con los pies. No tires con la lumbar redondeada.', 'Activá glúteos y cuádriceps generando tensión antes de despegar. Agarrá firme a los lados.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('dd6cb3bf-5912-5a67-9b64-b63296e198e0'::uuid, 'Sentadilla Goblet con Pausa', 'La sentadilla goblet con pausa sostiene la carga al pecho y mantiene unos segundos el fondo de la sentadilla antes de subir, reforzando el control, la movilidad y la fuerza en posición profunda.', 'Mantené el torso erguido durante la pausa. No rebotes desde el fondo.', 'Activá el core y los glúteos. Respirá manteniendo la tensión en la pausa.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('b208b0dc-ef9e-5daa-b534-8900802d1641'::uuid, 'Press de Banca con Pausa', 'El press con pausa detiene la barra sobre el pecho 1-2 segundos antes de empujar, eliminando el rebote y reforzando la fuerza desde el punto muerto. Es un accesorio clave para el powerlifting.', 'Mantené la tensión del cuerpo durante la pausa sin relajar. No hundas la barra en el pecho.', 'Retraé las escápulas y activá el tríceps. Apretá la barra fuerte en la pausa.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('30ee541a-36b6-53e4-822e-7d27a51b105e'::uuid, 'Press Inclinado con Mancuernas', 'El press inclinado con mancuernas empuja las cargas desde la parte alta del pecho con el banco inclinado, permitiendo un rango amplio y trabajo independiente de cada lado. Enfatiza el pectoral superior.', 'Controlá el estiramiento sin sobrecargar el hombro. Mantené las muñecas firmes.', 'Activá el pectoral superior con aperturas inclinadas livianas. Fijá las escápulas.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('6216223a-cf41-5d13-a9bb-e4feab1e6db1'::uuid, 'Press Pin (Pin Press)', 'El pin press empuja la barra desde pines fijos a la altura del pecho, eliminando la fase excéntrica y entrenando la fuerza desde el punto muerto. Es un accesorio para superar estancamientos en el press.', 'Ajustá los pines a la altura adecuada. Generá tensión antes de empujar desde parado.', 'Activá tríceps y pecho. Empujá explosivo desde los pines.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('f180b149-4a18-5b52-8cc4-ca0398009ee8'::uuid, 'Remo en T (T-Bar Row)', 'El remo en T usa una barra anclada por un extremo y un agarre en V, traccionando hacia el abdomen con el torso inclinado. Permite cargas altas y desarrolla el grosor de la espalda media.', 'Mantené la espalda neutra y evitá el balanceo excesivo. No redondees la lumbar.', 'Retraé las escápulas e iniciá el tirón desde los codos. Activá el dorsal.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('12885180-3349-5558-9333-4f4d62d33eec'::uuid, 'Pull Over en Polea', 'El pull over en polea con los brazos extendidos lleva la barra desde arriba hacia los muslos en arco, aislando el dorsal con tensión constante. Mantené una ligera flexión de codo fija.', 'No flexiones los codos para convertirlo en jalón. Mantené el core firme sin balancearte.', 'Activá el dorsal con repeticiones livianas. Sentí el estiramiento arriba.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('8e2f4d1d-01f8-52e2-88d3-7d2dfcc4d57a'::uuid, 'Pulldown con Agarre Neutro', 'El pulldown con agarre neutro tira de un agarre en V hacia el pecho, enfatizando la parte baja del dorsal con una posición de hombro más cómoda. Controlá la subida sin perder tensión.', 'Evitá inclinarte demasiado atrás. No uses impulso para bajar el agarre.', 'Deprimí las escápulas y tirá desde los codos. Activá el dorsal.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('416eb46e-93fb-5297-9cf1-578644b646e8'::uuid, 'Press Landmine', 'El press landmine empuja una barra anclada por un extremo en diagonal hacia arriba y adelante, trabajando el hombro con una trayectoria amable para la articulación. Ideal para hombros sensibles.', 'Mantené el core firme sin arquear la lumbar. Controlá la diagonal del empuje.', 'Activá deltoides y serrato. Empujá la barra siguiendo el ángulo natural.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('cdabe942-86df-5ac3-bc81-71c4984f049f'::uuid, 'Elevación Posterior en Pec Deck', 'La elevación posterior en máquina (pec deck invertido) abre los brazos hacia atrás contra la resistencia, aislando el deltoides posterior. Controlá el regreso sin perder la tensión.', 'No uses impulso del torso. Mantené una ligera flexión de codo constante.', 'Activá el deltoides posterior. Apretá las escápulas al abrir.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('e1152c67-eb6d-51a5-960e-8ffb1d2d12ef'::uuid, 'Press Militar Sentado en Máquina', 'El press de hombros en máquina empuja los agarres hacia arriba siguiendo una trayectoria guiada, permitiendo enfocar el deltoides con seguridad. Útil para acercarse al fallo sin estabilización.', 'Ajustá el asiento para alinear los agarres con los hombros. No bloquees los codos de golpe.', 'Activá deltoides con repeticiones livianas. Mantené la espalda apoyada.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('47a0bc27-ac7a-5bad-91a6-2b20e27724a0'::uuid, 'Curl Spider', 'El curl spider apoya el pecho en un banco inclinado con los brazos colgando verticales, flexionando los codos para aislar el bíceps con máxima tensión en la contracción. Sin impulso posible.', 'Mantené los brazos verticales y los codos fijos. No balancees el cuerpo.', 'Apretá fuerte el bíceps arriba. Controlá la fase negativa.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('eacee6fe-69b5-598a-abde-89fe445eef40'::uuid, 'Curl con Cable', 'El curl con cable flexiona los codos contra la polea baja, manteniendo tensión constante en el bíceps en todo el rango, a diferencia de los pesos libres. Controlá la bajada sin soltar la tensión.', 'No balancees el torso. Mantené los codos pegados al cuerpo.', 'Activá el bíceps y apretá arriba. Mantené la tensión en la bajada.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('1902255a-cfa0-5b39-8125-7ea2cb313e96'::uuid, 'Extensión Overhead con Mancuerna', 'La extensión overhead sostiene una mancuerna con ambas manos sobre la cabeza y la baja por detrás flexionando los codos, estirando y enfatizando la cabeza larga del tríceps. Mantené los codos apuntando arriba.', 'Controlá la bajada sin abrir los codos. Cuidá la zona del hombro en el estiramiento.', 'Activá el tríceps en el estiramiento. Extendé controlando arriba.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('3a270e96-bef4-5f45-990c-6f33c28e4177'::uuid, 'Extensión de Tríceps en Polea con Barra', 'La extensión en polea con barra recta empuja hacia abajo extendiendo los codos pegados al cuerpo, enfatizando las cabezas lateral y medial del tríceps. Controlá el regreso resistiendo la carga.', 'Mantené los codos fijos a los costados. No uses el peso del cuerpo para empujar.', 'Apretá el tríceps abajo. Activá con repeticiones controladas.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('fabefefc-a9ae-5930-8b1e-01e5fffb1030'::uuid, 'Gironda / Curl Inclinado en Polea', 'El curl inclinado en polea estira el bíceps con el brazo detrás del torso, generando una contracción aislada similar al curl en banco inclinado pero con tensión constante del cable. Controlá todo el rango.', 'Mantené los codos fijos y atrás. No balancees el hombro.', 'Activá el bíceps en el estiramiento. Apretá en la contracción.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('f59bacee-f382-585a-a084-a574a7f21f7f'::uuid, 'Elevación Lateral en Polea', 'La elevación lateral en polea baja sube el brazo hacia el costado contra la tensión del cable, manteniendo carga constante sobre el deltoides lateral incluso en el inicio del rango. Controlá la bajada.', 'No uses impulso de cadera. Mantené una ligera flexión de codo.', 'Activá el deltoide lateral. Liderá con el codo y controlá el regreso.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('8dfd1f3d-b210-57e0-9455-2e72dcecad63'::uuid, 'Sentadilla Sissy', 'La sentadilla sissy inclina el torso hacia atrás mientras flexiona las rodillas adelantándolas, estirando intensamente el cuádriceps. Es un ejercicio de aislamiento avanzado del cuádriceps con peso corporal.', 'Requiere buena salud de rodilla; progresá con apoyo. Controlá el rango sin forzar la articulación.', 'Activá el cuádriceps con repeticiones parciales. Mantené el core firme para equilibrar.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('794b0a3f-2e13-5722-899a-8871dcb130b7'::uuid, 'Nordic Curl', 'El nordic curl arrodillado con los tobillos fijos baja el torso al frente resistiendo con los isquiotibiales, siendo uno de los ejercicios más potentes para la fuerza excéntrica de isquios y la prevención de lesiones.', 'Bajá lo más controlado posible y amortiguá con las manos. No te dejes caer de golpe.', 'Activá los isquios con repeticiones asistidas. Progresá el rango gradualmente.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('46a42f4c-6def-53d3-a091-d085ded95191'::uuid, 'Hip Thrust a una Pierna', 'El hip thrust unilateral eleva la cadera apoyando una sola pierna, intensificando el trabajo del glúteo y exponiendo asimetrías. Apretá fuerte arriba manteniendo la pelvis nivelada.', 'Mantené la pelvis nivelada sin rotar. No hiperextiendas la lumbar arriba.', 'Activá el glúteo con puentes a una pierna. Empujá con el talón apoyado.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('ce46d0de-6db1-525a-98da-7f4049f677e0'::uuid, 'Step Up con Mancuernas', 'El step up sube a un cajón con una pierna sosteniendo mancuernas y baja controlado, trabajando la fuerza unilateral del tren inferior y el equilibrio. Empujá con la pierna de arriba sin impulsarte con la de abajo.', 'Controlá el descenso sin dejarte caer. Apoyá completamente el pie sobre el cajón.', 'Activá glúteo y cuádriceps. Subí empujando con el talón de la pierna superior.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('9050da90-ac95-5ab6-ab53-174d80401efb'::uuid, 'Combinación 1-2 al Saco', 'La combinación 1-2 encadena un jab seguido de un cross, el dúo fundamental del boxeo. Practicá la transición fluida entre ambos golpes manteniendo la guardia y el equilibrio. Desarrolla coordinación y ritmo ofensivo.', 'Vendá y enguantá las manos. Volvé siempre a la guardia tras la combinación.', 'Activá hombros y core con sombra. Coordiná la rotación de cadera en el cross.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('76ae11d9-dba6-553c-a4dd-e13079bd8423'::uuid, 'Golpeo de Rodillas (Muay Thai)', 'El rodillazo del muay thai impulsa la rodilla hacia arriba o adelante con un fuerte cierre de cadera y abdomen, típicamente en el clinch. Genera gran potencia desde el core y los flexores de cadera.', 'Cuidá el equilibrio al impactar; mantené el agarre o la guardia. No hiperextiendas la zona lumbar.', 'Activá core y flexores de cadera. Cerrá la cadera con potencia en cada rodillazo.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('be901cd3-d118-58cd-8add-699b4c2824f8'::uuid, 'Patada Baja (Low Kick)', 'la patada baja del kickboxing golpea con la espinilla a la altura del muslo rival, rotando la cadera y pivotando sobre el pie de apoyo. La potencia viene de la rotación de toda la cadena.', 'Pivoteá el pie de apoyo para no lesionar la rodilla. Acondicioná la espinilla progresivamente.', 'Activá cadera y oblicuos. Rotá todo el cuerpo en la patada.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('367babf9-3cc5-539f-8f40-603f418803c9'::uuid, 'Teep / Patada Frontal', 'El teep o patada frontal empuja con la planta del pie hacia adelante extendiendo la cadera y la rodilla, usado para mantener distancia. Es el jab de las piernas en muay thai. Retraé rápido a la guardia.', 'Mantené el equilibrio sobre la pierna de apoyo. No bloquees la rodilla al extender.', 'Activá flexores de cadera y core. Proyectá la cadera al empujar.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('199d2839-092a-51d4-a217-6ce181584d39'::uuid, 'Sprawl', 'El sprawl es la defensa antiderribo: desde de pie se lanzan las piernas hacia atrás cayendo en plancha para frenar un tackle. Es un movimiento explosivo clave en MMA y lucha, muy usado en circuitos.', 'Cuidá la lumbar al caer; mantené el core firme. Amortiguá con los brazos.', 'Activá core y piernas con saltos suaves. Reaccioná rápido bajando la cadera.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('2a330d20-c88a-5040-b763-ea3c9189a0b5'::uuid, 'Shadow Boxing con Mancuernas Livianas', 'El shadow boxing con mancuernas livianas ejecuta combinaciones sosteniendo poco peso, aumentando la resistencia de los hombros y la potencia de los golpes. No debe comprometer la técnica ni la velocidad.', 'Usá cargas muy livianas para no forzar el hombro ni los codos. No bloquees los codos al extender.', 'Activá hombros con movilidad. Mantené la técnica limpia pese al peso.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('22744721-a964-53ea-a8cd-13cbc9a6e1a4'::uuid, 'Golpeo al Speed Bag (Pera Veloz)', 'El speed bag golpea una pequeña pera con un ritmo constante de los puños, desarrollando timing, coordinación y resistencia de hombros. Es un clásico del entrenamiento de boxeo para la velocidad de manos.', 'Mantené los codos arriba y los hombros relajados pero activos. Cuidá las muñecas.', 'Activá hombros con círculos suaves. Encontrá un ritmo constante antes de acelerar.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('2fd769cc-ab67-5c32-8b67-eb9e6808ac2b'::uuid, 'Clean Wall Ball Complex', 'Este complejo encadena una cargada con un wall ball, combinando potencia de cadera con lanzamiento y sentadilla en un patrón metabólico continuo. Muy común en WODs para elevar la intensidad cardiovascular.', 'Mantené la espalda neutra en cada cargada. Recibí el balón amortiguando hacia la sentadilla.', 'Activá piernas y hombros. Mantené un ritmo sostenible en las repeticiones.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('e2b66d32-3884-5397-9817-dbf3c1343dd4'::uuid, 'Dumbbell Thruster', 'El thruster con mancuernas hace una sentadilla frontal con las mancuernas en los hombros y las empuja overhead con la extensión de cadera. Permite trabajar el patrón de thruster con cargas independientes por lado.', 'Mantené el core firme y los codos algo elevados. No arquees la lumbar al empujar.', 'Activá piernas y hombros con repeticiones livianas. Coordiná la subida con el empuje.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('7551052d-2906-5765-9720-ebe0291273bf'::uuid, 'Sandbag Carry', 'El transporte de sandbag carga un saco de arena al pecho o al hombro y camina una distancia, demandando fuerza de core, agarre y resistencia. Es un ejercicio funcional típico de strongman y crossfit.', 'Mantené la espalda neutra al levantar y caminar. No dejes que el saco te incline.', 'Activá core y piernas antes de levantar. Abrazá firme el saco.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('d6884621-93e7-5438-bbcf-deabed42383e'::uuid, 'Ball Slam', 'El ball slam eleva un balón medicinal por encima de la cabeza y lo estrella contra el suelo con toda la fuerza, extendiendo y luego flexionando el cuerpo. Es un descargador de potencia y un clásico metabólico.', 'Flexioná las rodillas al recoger el balón, no la espalda. Mantené la columna neutra.', 'Activá core y dorsal. Extendé el cuerpo arriba antes de lanzar con fuerza.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('1aa9c762-945c-5081-a6b5-947408f5a33f'::uuid, 'Rope Climb (Trepar la Cuerda)', 'La trepa de cuerda asciende usando brazos y piernas con una técnica de bloqueo de pies, desarrollando una enorme fuerza de agarre y tirón. Es un movimiento icónico del crossfit y el entrenamiento militar.', 'Aprendé la técnica de bloqueo de pies antes de subir. Bajá controlado para no quemarte las manos.', 'Activá agarre y dorsal con dead hangs. Coordiná el empuje de piernas con el tirón.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('b870caac-5040-5057-a0ff-3751bdbd9b62'::uuid, 'Box Step Over', 'El box step over sube sobre un cajón y baja por el otro lado de forma continua, una alternativa de menor impacto al box jump usada en WODs largos. Mantené un ritmo constante y el control del paso.', 'Apoyá completamente el pie en el cajón. Controlá el descenso del otro lado.', 'Activá glúteos y cuádriceps. Mantené un ritmo sostenible.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('8fdc93e6-d977-570e-beb5-8da53681be71'::uuid, 'Power Snatch', 'El power snatch lleva la barra del suelo a overhead en un movimiento explosivo recibiéndola en cuarto de sentadilla, sin bajar a la sentadilla completa. Entrena la potencia del tirón olímpico, muy usado en WODs.', 'Mantené la barra cerca del cuerpo y la columna neutra. Estabilizá el hombro en el bloqueo overhead.', 'Activá la cadena posterior con tirones livianos. Movilizá hombros y muñecas.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('a0a5a121-d04d-5d32-8d24-63b8ea482a6e'::uuid, 'Sled Push (Empuje de Trineo)', 'El sled push empuja un trineo cargado caminando o corriendo, desarrollando potencia de piernas y capacidad anaeróbica con cero fase excéntrica, lo que reduce el daño muscular. Excelente para velocistas y deportistas.', 'Mantené los brazos firmes y la espalda neutra. Empujá con pasos potentes sin redondear la lumbar.', 'Activá glúteos y cuádriceps. Inclinate hacia adelante y empujá con fuerza constante.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('ce3aaea2-817f-5ebe-8e4c-6401c9161041'::uuid, 'Sled Pull (Arrastre de Trineo)', 'El sled pull arrastra un trineo cargado caminando hacia atrás o tirando con una cuerda, trabajando la cadena posterior y el agarre. Complementa al empuje y mejora la aceleración.', 'Mantené la espalda neutra y traccioná con piernas y espalda. No tires solo con los brazos.', 'Activá isquios y dorsal. Mantené la tensión constante en el arrastre.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('fb00bdb1-b734-58e9-b9a5-5459360df06f'::uuid, 'A-Skip', 'El A-skip es un ejercicio de técnica de carrera que combina un salto con elevación de rodilla y apoyo activo en el metatarso, mejorando la mecánica, la rigidez del tobillo y la frecuencia de zancada.', 'Apoyá en el metatarso y mantené el tobillo rígido. No te eches hacia atrás.', 'Activá flexores de cadera y pantorrillas. Coordiná brazos y piernas con ritmo.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('7d212330-f3a7-5025-98b6-bfe5515469c1'::uuid, 'Salto al Cajón Lateral', 'El salto lateral al cajón se proyecta de costado hacia el cajón, entrenando la potencia en el plano frontal y el glúteo medio, relevante para deportes con cambios de dirección. Aterrizá con control.', 'Aterrizá con la rodilla flexionada y alineada. Empezá con cajones bajos.', 'Activá glúteo medio y cuádriceps. Proyectá la cadera hacia el lado.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('5a5eaa0d-b8ce-59fd-8082-6081552fe36b'::uuid, 'Pull Buoy / Lat Pull en Seco (Banda)', 'El trabajo en seco para natación con banda simula la fase de tracción de la brazada, fortaleciendo el dorsal y los hombros en el patrón específico del nado. Mantené la técnica de la brazada controlada.', 'Mantené los hombros estables y la técnica limpia. No tires con balanceo de torso.', 'Activá dorsal y hombros. Reproducí la trayectoria de la brazada.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('5ddd84a0-8a7f-514f-8085-84ba51a75bfa'::uuid, 'Rotación Externa de Hombro con Banda', 'La rotación externa con banda fortalece el manguito rotador, esencial para la salud del hombro de nadadores y lanzadores. Con el codo pegado al cuerpo, rotá el antebrazo hacia afuera contra la banda.', 'Usá poca resistencia y prioriza la técnica. Mantené el codo pegado al costado.', 'Activá los rotadores con repeticiones lentas. No uses impulso.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('d23181a8-5483-5a71-9682-702ee5c95b0d'::uuid, 'Pallof Press', 'El pallof press empuja un cable o banda al frente desde el costado del cuerpo, resistiendo la rotación que genera la carga. Entrena la fuerza antirotación del core, clave para todos los deportes.', 'Mantené la cadera y los hombros estables sin rotar. No contengas la respiración.', 'Activá el core antes de empujar. Resistí la rotación durante todo el rango.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('d74de61a-e0b9-5fd9-92b8-b466af4c6124'::uuid, 'Copenhagen Plank', 'La plancha de Copenhague apoya el pie superior en un banco y sostiene el cuerpo de costado con la pierna de arriba, exigiendo intensamente los aductores. Es excelente para la prevención de lesiones de ingle.', 'Progresá desde la versión con rodilla apoyada. Mantené la cadera elevada sin rotar.', 'Activá aductores y core. Mantené el cuerpo en línea.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('fff65ae4-aecc-51f7-9a46-35859c888331'::uuid, 'Cargada Colgante (Hang Clean)', 'El hang clean inicia la cargada desde la posición colgante (barra a la altura de las rodillas o muslos) en lugar del suelo, enfatizando la segunda fase del tirón y la potencia de cadera. Muy usado para enseñar el clean.', 'Mantené la barra cerca del cuerpo y la columna neutra. Recibí con los codos altos.', 'Activá glúteos e isquios con tirones colgantes. Generá potencia desde la cadera.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('4e123551-27df-59f9-8071-9fa2a3618990'::uuid, 'Arranque Colgante (Hang Snatch)', 'El hang snatch ejecuta el arranque desde la posición colgante, reforzando la potencia de la segunda fase del tirón y la velocidad de recepción overhead. Es un ejercicio de técnica para el snatch completo.', 'Mantené la barra cerca y la espalda neutra. Estabilizá el hombro en la recepción overhead.', 'Movilizá hombros y muñecas. Acelerá fuerte en la extensión de cadera.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('0b54a0a7-ad6f-59ff-8a38-e3f146197080'::uuid, 'Push Press con Mancuernas', 'El push press con mancuernas usa un impulso de piernas para ayudar a empujar las cargas overhead, permitiendo mover más peso que el press estricto y entrenando la transferencia de fuerza pierna-hombro.', 'Coordiná el dip de piernas con el empuje. No arquees la lumbar al bloquear.', 'Activá piernas y hombros con dip-drives. Mantené el core firme.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('90280657-3809-51d2-a49e-29ee91674cbf'::uuid, 'Clean Pull (Tirón de Cargada)', 'El clean pull realiza el tirón de la cargada sin la recepción, enfatizando la extensión explosiva de cadera y el encogimiento de trapecios con cargas potencialmente altas. Acelerá al máximo en la extensión.', 'Mantené la columna neutra y la barra cerca. No redondees la lumbar en el despegue.', 'Activá la cadena posterior. Generá tensión antes de despegar y acelerá arriba.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('e2cb03d7-515f-58e5-abfd-423d88dcba14'::uuid, 'Aperturas en Pec Deck', 'Las aperturas en pec deck juntan los brazos al frente contra las almohadillas de la máquina, aislando el pectoral con una trayectoria guiada y tensión constante. Apretá el pecho al juntar y controlá el regreso.', 'Ajustá el asiento para alinear los codos con los hombros. No fuerces el estiramiento hacia atrás.', 'Activá el pectoral con repeticiones livianas. Apretá un segundo al juntar.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('36ea96fe-c819-5b67-8955-10443299c0b9'::uuid, 'Remo en Máquina Hammer', 'El remo en máquina Hammer tira de los agarres hacia el torso con apoyo del pecho, permitiendo enfocar la espalda sin estabilizar la lumbar. Ideal para cargar y acercarse al fallo con seguridad.', 'Apoyá bien el pecho y no despegues el torso. Retraé las escápulas en cada tirón.', 'Activá el dorsal iniciando desde los codos. Apretá la espalda al final.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('3d0f7b7a-16ce-57f4-ae36-b5f6818239da'::uuid, 'Pulldown a un Brazo', 'El pulldown a un brazo tira de la polea alta de forma unilateral, permitiendo un rango mayor y corregir asimetrías del dorsal. Controlá la subida sintiendo el estiramiento del dorsal.', 'Evitá rotar el torso para ayudarte. Mantené la cadera estable.', 'Deprimí la escápula y tirá desde el codo. Activá el dorsal de cada lado.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('636da18f-5bb9-512b-a97a-580d08c45d63'::uuid, 'Curl Femoral Sentado', 'El curl femoral sentado flexiona las rodillas hacia abajo contra la almohadilla con el torso apoyado, aislando los isquiotibiales en una posición de mayor estiramiento que la versión tumbada.', 'Ajustá la almohadilla sobre los tobillos. No uses impulso de cadera.', 'Activá los isquios con repeticiones livianas. Controlá la fase de regreso.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('fb59b7d7-2977-5298-9a26-5961aa21c326'::uuid, 'Extensión Lumbar en Máquina', 'La extensión lumbar en máquina extiende el torso hacia atrás contra el respaldo acolchado, fortaleciendo los erectores de la columna de forma guiada y segura. Subí hasta la línea neutra controlando.', 'No hiperextiendas la columna; pará en la posición neutra. Controlá el regreso.', 'Activá los erectores con repeticiones livianas. Mantené el movimiento controlado.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('d1584a70-c3e4-5696-a44f-89c51c349213'::uuid, 'Abducción de Cadera con Banda (Monster Walk)', 'El monster walk coloca una banda alrededor de las rodillas o tobillos y camina lateralmente manteniendo la tensión, activando intensamente el glúteo medio. Es base para el calentamiento de cadera y rodilla.', 'Mantené las rodillas alineadas sin que colapsen hacia adentro. Conservá la tensión de la banda.', 'Activá el glúteo medio. Caminá con pasos controlados manteniendo la semisentadilla.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('4ad28401-d3a7-50b6-a77c-2bd06b60e944'::uuid, 'Press de Hombro Landmine de Rodillas', 'El press landmine de rodillas empuja la barra anclada en diagonal desde una posición arrodillada, eliminando el impulso de piernas y enfocando el hombro y el serrato. Mantené el core firme.', 'No arquees la lumbar al empujar. Mantené la cadera extendida y el core activo.', 'Activá deltoides y serrato. Empujá siguiendo la diagonal natural.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('ef9b5d8d-42c3-59aa-a1be-371ffe54f551'::uuid, 'Dips en Anillas', 'Los dips en anillas descienden y empujan el cuerpo sobre anillas inestables, añadiendo una enorme demanda de estabilización frente a los dips en barra fija. Desarrollan fuerza y control del empuje vertical.', 'Estabilizá las anillas pegándolas al cuerpo. Bajá solo hasta donde controles el hombro.', 'Activá pecho, tríceps y estabilizadores. Mantené las anillas firmes y rotadas hacia afuera.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('71da8799-2f4d-534e-8855-d2d87fafb7ad'::uuid, 'L-Sit', 'El L-sit sostiene el cuerpo apoyado en las manos con las piernas extendidas al frente formando una L, exigiendo intensamente el core, los flexores de cadera y el tríceps de forma isométrica.', 'Deprimí las escápulas y mantené los brazos firmes. Progresá desde piernas flexionadas.', 'Activá core y tríceps. Empujá el suelo manteniendo los hombros bajos.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('72780416-85db-55b2-a4d7-133299a48913'::uuid, 'Remo Australiano en Anillas', 'El remo en anillas tira del cuerpo hacia las anillas manteniéndolo recto, con la inestabilidad sumando demanda de estabilización a la espalda. Regulá la dificultad cambiando la inclinación del cuerpo.', 'Mantené el cuerpo en línea sin dejar caer la cadera. Retraé las escápulas al tirar.', 'Activá dorsal y romboides. Iniciá el tirón desde los codos.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('1ed62f5e-6b1e-5b4c-b3ff-36d39a2d4027'::uuid, 'Pike Push Up', 'El pike push up coloca el cuerpo en forma de V invertida y baja la cabeza hacia el suelo flexionando los codos, trabajando el empuje vertical de los hombros con el peso corporal. Es progresión hacia el handstand push up.', 'Protegé el cuello bajando controlado. Mantené la cadera elevada en V.', 'Activá hombros y tríceps. Bajá la coronilla hacia el suelo con control.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('f0c2ae6f-be82-5a20-8862-0c1eaec9ec22'::uuid, 'Sentadilla con Salto a una Pierna', 'La sentadilla con salto unilateral desciende sobre una pierna y salta con potencia, demandando fuerza, equilibrio y control reactivo del tren inferior. Es avanzada y útil para deportes de salto.', 'Aterrizá con la rodilla flexionada y alineada. Dominá la fuerza unilateral antes de saltar.', 'Activá glúteo y cuádriceps. Controlá el aterrizaje en cada repetición.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('ec48966c-7600-5ef2-bc69-95253a5527f2'::uuid, 'Plate Pinch', 'El plate pinch sostiene uno o varios discos por sus caras lisas con los dedos, desarrollando la fuerza de pinza del agarre. Es muy específico para escaladores, levantadores y deportes de lucha.', 'Empezá con discos livianos y superficies que controles. Soltá con cuidado para no golpearte los pies.', 'Activá los dedos y antebrazos. Apretá con firmeza durante el sostén.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('efbbf93c-9a18-55bc-a938-3168b5e0ff30'::uuid, 'Wrist Roller (Enrollador de Muñeca)', 'El wrist roller enrolla una cuerda con peso alrededor de una barra girando las muñecas, trabajando intensamente flexores y extensores del antebrazo. Hacé subir y bajar la carga de forma controlada.', 'Usá cargas moderadas para no estresar las muñecas. Mantené los brazos extendidos sin balancear.', 'Activá los antebrazos con un par de giros suaves. Controlá la bajada de la carga.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('626196e8-9622-5d21-8ccc-2b37efb84627'::uuid, 'Reverse Wrist Curl', 'El reverse wrist curl apoya los antebrazos y eleva el dorso de las manos con una barra en agarre prono, aislando los extensores del antebrazo. Equilibra el trabajo de los flexores y previene lesiones de codo.', 'Usá poco peso; los extensores son pequeños. Controlá el rango completo de muñeca.', 'Activá los extensores con repeticiones lentas. Elevá el dorso de la mano controlando.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('a12dcd70-235e-584d-802e-94a27cd922af'::uuid, 'Ab Wheel de Pie', 'La rueda abdominal de pie rueda hacia adelante desde la posición erguida y vuelve contrayendo el core, siendo la versión más avanzada del ejercicio. Demanda una fuerza y antiextensión del abdomen extremas.', 'Requiere base previa con la versión de rodillas. No dejes que la lumbar se arquee.', 'Activá el core al máximo antes de rodar. Avanzá solo hasta donde controles.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('9c330bc2-771b-599f-9a00-6f86538e7313'::uuid, 'Cable Woodchopper', 'El woodchopper en polea lleva el cable en diagonal de arriba a abajo (o viceversa) rotando el tronco, entrenando la potencia rotacional del core. Es transferible a golpes, lanzamientos y swings deportivos.', 'Generá la rotación desde el tronco, no solo los brazos. Mantené la cadera controlada.', 'Activá los oblicuos. Acompañá la diagonal con la rotación del torso.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('4ffcfcb2-ae31-5b8c-ac0d-533869dcde1a'::uuid, 'Neck Flexion con Disco', 'La flexión de cuello acostado con un disco apoyado en la frente flexiona la cabeza hacia el pecho contra la resistencia, fortaleciendo la musculatura cervical anterior. Esencial en deportes de contacto.', 'Usá cargas muy livianas y rango controlado. Detené el ejercicio ante cualquier molestia cervical.', 'Activá el cuello con movimientos suaves sin peso. Progresá la carga muy gradualmente.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('abad57fa-64ce-528d-b1a7-11f2ab38b30b'::uuid, 'Suitcase Carry', 'El suitcase carry camina sosteniendo una carga pesada en un solo lado, obligando al core a resistir la flexión lateral. Entrena la estabilidad antilateral y el agarre de forma muy funcional.', 'Mantené el torso completamente erguido sin inclinarte. No dejes que el hombro caiga.', 'Activá oblicuos y core antes de levantar. Caminá con pasos controlados y firmes.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('9674b2f2-cf3e-5a8e-9516-e3b0347129b0'::uuid, 'Sentadilla Frontal con Mancuernas', 'La sentadilla frontal con mancuernas apoya las cargas sobre los hombros y desciende manteniendo el torso vertical, enfatizando el cuádriceps con una alternativa accesible a la barra. Mantené los codos elevados.', 'Mantené el torso erguido y los codos altos. No dejes caer el pecho en el descenso.', 'Activá cuádriceps y core. Mantené las mancuernas estables sobre los hombros.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('01c600ab-c7c8-597a-b894-2a2d6ac28ea4'::uuid, 'Zancada Caminando con Barra', 'La zancada caminando avanza alternando piernas con una barra en la espalda, desarrollando fuerza unilateral, equilibrio y resistencia del tren inferior bajo carga. Mantené el torso erguido en cada paso.', 'Controlá que la rodilla delantera no colapse hacia adentro. Mantené el equilibrio antes de avanzar.', 'Activá glúteos y cuádriceps. Dá pasos controlados manteniendo el torso firme.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('bdfa9574-6f19-52a7-8337-013c4e54d875'::uuid, 'Peso Muerto a una Pierna con Mancuerna', 'El peso muerto a una pierna baja la mancuerna mientras la pierna libre se extiende hacia atrás, entrenando la cadena posterior, el equilibrio y la estabilidad de cadera de forma unilateral.', 'Mantené la columna neutra y la cadera nivelada. No redondees la espalda al bajar.', 'Activá glúteo e isquios con el patrón de bisagra. Buscá el equilibrio antes de cargar.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('fc269ec5-ab4d-5120-b6d6-c92c04c3b40a'::uuid, 'Sentadilla en Caja (Box Squat)', 'La sentadilla en caja desciende hasta sentarse brevemente en un cajón antes de subir, reforzando el patrón de cadera, el control y la fuerza desde el punto muerto. Es un accesorio clásico de powerlifting.', 'No te dejes caer sobre la caja; sentate controlado. Mantené la tensión en la pausa.', 'Activá glúteos e isquios. Empujá el piso para subir sin perder la tensión.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('ed5e9618-36d9-5e5a-aa0e-01b85b6930b2'::uuid, 'Battle Ropes', 'Las battle ropes ondean dos cuerdas pesadas de forma alternada o simultánea, generando un estímulo cardiovascular y de resistencia de hombros muy intenso. Mantené una semisentadilla y un ritmo constante.', 'Mantené la espalda neutra y las rodillas algo flexionadas. No encojas los hombros en exceso.', 'Activá hombros y core. Generá las ondas desde todo el cuerpo, no solo los brazos.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('5f4010e7-2edd-5fca-994c-7f51b51dd279'::uuid, 'Mountain Climbers', 'Los mountain climbers en plancha llevan las rodillas al pecho de forma rápida y alternada, combinando trabajo de core con un fuerte estímulo cardiovascular. Mantené la cadera baja y estable.', 'No dejes que la cadera suba o se hunda. Mantené los hombros sobre las muñecas.', 'Activá el core antes de empezar. Mantené un ritmo constante y controlado.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('693ff6e2-d971-5582-8368-d97af9419206'::uuid, 'Jumping Jacks', 'Los jumping jacks abren y cierran brazos y piernas con un salto, un ejercicio de calentamiento y acondicionamiento cardiovascular de cuerpo completo, accesible y de bajo equipamiento. Mantené un ritmo fluido.', 'Aterrizá suave sobre el metatarso para cuidar las articulaciones. Mantené los hombros relajados.', 'Activá el cuerpo con un ritmo progresivo. Coordiná brazos y piernas.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('96b3a73d-a02b-5f06-8eae-844289e09357'::uuid, 'Burpee Box Jump Over', 'El burpee box jump over encadena un burpee con un salto sobre el cajón, combinando flexión de pecho, potencia de salto y alta demanda metabólica. Es uno de los movimientos más exigentes en WODs.', 'Cuidá la lumbar en el burpee y la recepción del salto. Bajá del cajón con control.', 'Activá el cuerpo con saltos y planchas suaves. Mantené un ritmo sostenible.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('7d6cf16f-edbf-5581-b28a-81baad57a425'::uuid, 'Thruster con Kettlebells', 'El thruster con kettlebells hace una sentadilla frontal con las pesas en el rack y las empuja overhead con la extensión de cadera. La posición del rack con kettlebells añade demanda de estabilidad del core.', 'Mantené el core firme y los codos cerca del cuerpo. No arquees la lumbar al empujar.', 'Activá piernas y hombros con repeticiones livianas. Coordiná la subida con el empuje.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('79058bf0-4195-57da-af54-fe9f6644a9bb'::uuid, 'Inchworm', 'El inchworm desde de pie baja las manos al suelo, camina hasta la plancha, hace opcionalmente una flexión y regresa caminando las manos. Combina movilidad, core y trabajo de empuje, ideal para calentar.', 'Mantené las piernas lo más extendidas que tu movilidad permita. No dejes caer la cadera en plancha.', 'Activá el core y entrá en calor con movimiento suave. Controlá cada fase.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('96aa0910-fe8b-5d14-9e7f-d48621c3e773'::uuid, 'Sentadilla Isométrica en Pared (Wall Sit)', 'La wall sit mantiene una posición de sentadilla con la espalda apoyada en la pared y los muslos paralelos al suelo, entrenando la resistencia isométrica del cuádriceps. Sostené la posición el tiempo objetivo.', 'Mantené las rodillas a 90 grados sin pasar la punta del pie. No contengas la respiración.', 'Activá el cuádriceps al adoptar la posición. Mantené la espalda pegada a la pared.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('27d023d5-4df9-53e2-878a-4c45d51afbc0'::uuid, 'Press de Banca Declinado', 'El press declinado empuja la barra con el banco inclinado hacia abajo, enfatizando la porción inferior del pectoral. Bajá la barra hacia la parte baja del pecho y empujá controlando. Complementa el desarrollo del pecho.', 'Asegurá bien las piernas en los soportes. No bajes la barra demasiado alto hacia el cuello.', 'Activá el pectoral inferior con repeticiones livianas. Retraé las escápulas.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('1e3ba24e-0784-5933-a7b0-5e6551c1a4f1'::uuid, 'Remo al Mentón con Barra', 'El remo al mentón eleva la barra cerca del cuerpo hasta la altura del pecho con los codos liderando, trabajando el deltoides lateral y el trapecio. Usá un agarre que no fuerce los hombros.', 'No subas la barra por encima de los hombros si genera pinzamiento. Mantené los codos por encima de las muñecas.', 'Activá deltoides y trapecio. Liderá el movimiento con los codos.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('0b9a19ca-139d-55a3-9aa9-3baba94c12b5'::uuid, 'Curl 21s', 'El curl 21s combina 7 repeticiones de medio rango inferior, 7 de medio rango superior y 7 completas, generando una enorme tensión metabólica en el bíceps. Es una técnica de intensidad para el brazo.', 'Usá una carga menor a la habitual. Mantené los codos fijos durante las 21 repeticiones.', 'Activá el bíceps antes de empezar. Mantené la técnica pese a la fatiga.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('a79f5d2f-41f9-5dce-82a7-88aff6c4b3f5'::uuid, 'Sentadilla Zercher', 'La sentadilla Zercher sostiene la barra en el pliegue de los codos frente al cuerpo, exigiendo mucho al core y la espalda alta mientras se hace la sentadilla. Es un accesorio de fuerza muy demandante del torso.', 'Usá una almohadilla en los codos por comodidad. Mantené el torso erguido y el core firme.', 'Activá core y erectores. Mantené los codos altos sosteniendo la barra.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('483f6976-9b8d-5c8d-8d81-45777c9b9531'::uuid, 'Patada de Glúteo en Polea', 'La patada de glúteo en polea extiende una pierna hacia atrás contra la resistencia del cable con una tobillera, aislando el glúteo mayor. Apretá el glúteo en la extensión y controlá el regreso.', 'No hiperextiendas la lumbar; el movimiento viene de la cadera. Mantené el torso estable.', 'Activá el glúteo apretando en la extensión. Controlá toda la fase de regreso.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('abc59544-dd37-558f-b002-7a6612ff006f'::uuid, 'Encogimiento de Hombros en Máquina', 'El encogimiento en máquina eleva los hombros contra la resistencia guiada, aislando el trapecio superior sin necesidad de estabilizar pesos libres. Subí y apretá arriba un instante.', 'No rotes los hombros. Mantené el cuello relajado.', 'Apretá el trapecio arriba. Activá con repeticiones controladas.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('b78dec41-24dd-5129-9620-91466ba1171c'::uuid, 'Flexión Pliométrica', 'La flexión pliométrica empuja el cuerpo con fuerza explosiva hasta despegar las manos del suelo, entrenando la potencia del empuje horizontal. Es avanzada y requiere base de fuerza previa.', 'Aterrizá con los codos flexionados para amortiguar. Requiere fuerza previa en flexiones estándar.', 'Activá pecho y tríceps con flexiones normales. Generá potencia desde el pecho.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('77c0c5d3-4c73-57d8-b843-c0d524092d66'::uuid, 'Clean and Jerk con Kettlebell', 'El clean and jerk con kettlebell lleva la pesa al rack y luego overhead con impulso de piernas, combinando potencia de cadera y empuje en un patrón unilateral funcional muy completo.', 'Controlá la cargada para que la pesa no golpee el antebrazo. Estabilizá el hombro overhead.', 'Activá cadera y hombro. Coordiná el dip de piernas con el empuje.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('45086436-9959-534a-80e6-8d6bbb28ad0a'::uuid, 'Snatch Grip Deadlift', 'El peso muerto con agarre de arranque usa un agarre muy ancho, aumentando el rango de recorrido y la demanda de la espalda alta y el agarre. Es un accesorio para fortalecer el tirón del snatch.', 'Mantené la espalda neutra pese al mayor rango. No redondees la lumbar en el despegue.', 'Activá la cadena posterior y el agarre. Generá tensión antes de despegar.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('f5dc253b-b8e1-57da-baaf-ce97dbcffeaf'::uuid, 'Deficit Push Up (Flexión con Déficit)', 'La flexión con déficit eleva las manos sobre apoyos para aumentar el rango de descenso del pecho, intensificando el estiramiento y el trabajo del pectoral. Bajá controlado hasta el máximo rango cómodo.', 'No fuerces el estiramiento del hombro. Mantené el cuerpo en línea recta.', 'Activá el pecho antes de bajar. Mantené la cadera firme.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('4517a7d5-66c8-5670-98a5-4158382db26c'::uuid, 'Glute Bridge con Barra', 'El glute bridge eleva la cadera desde el suelo con una barra apoyada sobre la pelvis, aislando el glúteo con un rango menor que el hip thrust. Es accesible y excelente para activar el glúteo.', 'Usá una almohadilla en la barra. Apretá el glúteo arriba sin hiperextender la lumbar.', 'Activá el glúteo con puentes sin peso. Empujá con los talones.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03'),
    ('fda70bee-d6f9-5d54-bf57-dea338281ae9'::uuid, 'Sentadilla Cossack', 'La sentadilla cossack desplaza el peso lateralmente sobre una pierna flexionada mientras la otra se extiende, trabajando aductores, movilidad de cadera y fuerza en el plano frontal. Mantené el talón apoyado.', 'Controlá el rango según tu movilidad. Mantené el talón de la pierna activa en el suelo.', 'Activá aductores y glúteos. Movilizá la cadera antes de cargar peso.', NULL, NULL, NULL, '2026-06-14 12:00:00-03', '2026-06-14 12:00:00-03')
